"use client";

import * as React from "react";

import type { ViewerResource } from "@/lib/viewer-resource";

import { CodeViewerFallback } from "./code-viewer-chrome";
import { CodeViewerContent } from "./code-viewer-content";
import type { CodeViewerHandle, CodeViewerProps } from "./code-viewer-types";
import { PlainTextViewerFrame } from "./plain-text-viewer-frame";

export type {
  CodeDocumentSource,
  CodeLineRange,
  CodeViewerHandle,
  CodeViewerProps,
} from "./code-viewer-types";

export type CodeResourceContentProps = Omit<CodeViewerProps, "source"> & {
  resource: ViewerResource;
};

export const CodeViewer = React.forwardRef<CodeViewerHandle, CodeViewerProps>(
  function CodeViewer(props, ref) {
    return (
      <PlainTextViewerFrame
        props={props}
        forwardedRef={ref}
        clientFallbackPolicy="always"
        contentResetPolicy="inline-retry"
        Fallback={CodeViewerFallback}
        Content={CodeViewerContent}
      />
    );
  },
);

export const CodeResourceContent = React.forwardRef<
  CodeViewerHandle,
  CodeResourceContentProps
>(function CodeResourceContent({ resource, ...props }, ref) {
  return (
    <PlainTextViewerFrame
      props={props}
      resource={resource}
      forwardedRef={ref}
      clientFallbackPolicy="always"
      contentResetPolicy="inline-retry"
      Fallback={CodeViewerFallback}
      Content={CodeViewerContent}
    />
  );
});

"use client";

import * as React from "react";

import { type ViewerDownloadAction } from "@/lib/viewer-download-actions";

import { Skeleton } from "./skeleton";
import { TextCodeViewerFrame } from "./text-code-viewer-chrome";
import {
  ViewerControls,
  ViewerControlsSkeleton,
  type ViewerControlsState,
} from "./viewer-controls";

export function CodeViewerFrame({
  className,
  bare,
  children,
}: {
  className?: string;
  bare?: boolean;
  children: React.ReactNode;
}) {
  return (
    <TextCodeViewerFrame
      bare={bare}
      bareClassName="h-full bg-muted/20"
      className={className}
      dataSlot="code-viewer"
      framedClassName="rounded-xl border bg-muted/30"
    >
      {children}
    </TextCodeViewerFrame>
  );
}

export function CodeViewerControls({
  lineCount,
  fontScale,
  downloadAction,
  onZoomOut,
  onZoomIn,
  onResetZoom,
}: {
  lineCount: number;
  fontScale: number;
  downloadAction?: ViewerDownloadAction | null;
  onZoomOut: () => void;
  onZoomIn: () => void;
  onResetZoom: () => void;
}) {
  const controlsState = codeViewerControlsState({
    lineCount,
    fontScale,
    downloadAction,
    onZoomOut,
    onZoomIn,
    onResetZoom,
  });

  return (
    <ViewerControls
      title={controlsState.title}
      zoom={controlsState.zoom}
      downloads={controlsState.downloads}
    />
  );
}

export function codeViewerControlsState({
  lineCount,
  fontScale,
  downloadAction,
  onZoomOut,
  onZoomIn,
  onResetZoom,
}: {
  lineCount: number;
  fontScale: number;
  downloadAction?: ViewerDownloadAction | null;
  onZoomOut: () => void;
  onZoomIn: () => void;
  onResetZoom: () => void;
}): ViewerControlsState {
  return {
    title: `${lineCount} line${lineCount === 1 ? "" : "s"}`,
    zoom: {
      scale: fontScale,
      onZoomOut,
      onZoomIn,
      onFit: onResetZoom,
      fitLabel: "Reset zoom",
    },
    downloads: downloadAction ? [downloadAction] : [],
  };
}

export function CodeViewerFallback({
  className,
  controls = true,
  download = true,
  bare,
}: {
  className?: string;
  controls?: boolean;
  download?: boolean;
  bare?: boolean;
}) {
  return (
    <CodeViewerFrame className={className} bare={bare}>
      {controls ? (
        <ViewerControlsSkeleton title zoom download={download} />
      ) : null}
      <div
        className="min-h-0 flex-1 space-y-2 overflow-hidden p-4"
        data-slot="code-body-skeleton"
      >
        {Array.from({ length: 12 }, (_, index) => (
          <Skeleton
            key={index}
            className="h-4"
            style={{ width: `${40 + ((index * 13) % 55)}%` }}
          />
        ))}
      </div>
    </CodeViewerFrame>
  );
}

"use client";

import * as React from "react";

import { cn } from "@/lib/utils";

export function TextCodeViewerFrame({
  bare,
  bareClassName,
  children,
  className,
  dataSlot,
  framedClassName,
}: {
  bare?: boolean;
  bareClassName: string;
  children: React.ReactNode;
  className?: string;
  dataSlot: string;
  framedClassName: string;
}) {
  return (
    <div
      className={cn(
        "flex min-h-0 flex-col overflow-hidden",
        bare ? bareClassName : framedClassName,
        className,
      )}
      data-slot={dataSlot}
    >
      {children}
    </div>
  );
}

"use client";

import * as React from "react";

import {
  isResourceError,
  isViewerFormatError,
  isViewerStateError,
  isViewerUnsupportedError,
  ViewerFormatError,
} from "@/lib/viewer-errors";
import {
  createViewerResource,
  viewerContentRenderKey,
  viewerResourceRenderKey,
  type ViewerResource,
} from "@/lib/viewer-resource";
import type {
  BlobViewerSource,
  TextSource,
  UrlViewerSource,
} from "@/lib/viewer-source";

import {
  DEFAULT_MAX_BYTES,
  DEFAULT_MAX_LINES,
  type TextViewerBounds,
} from "./plain-text-resource";
import { useIsClient } from "./use-is-client";
import { ViewerErrorBoundary } from "./viewer-error";

type TextResourceSource = UrlViewerSource | BlobViewerSource | TextSource;
type ClientFallbackPolicy = "always" | "non-inline-source";
type ContentResetPolicy = "content" | "inline-retry";

export interface PlainTextViewerFrameProps<
  THandle,
  TProps extends PlainTextViewerFramePublicProps,
> {
  props: TProps;
  resource?: ViewerResource;
  forwardedRef: React.ForwardedRef<THandle>;
  clientFallbackPolicy: ClientFallbackPolicy;
  contentResetPolicy?: ContentResetPolicy;
  Fallback: React.ComponentType<PlainTextViewerFallbackProps>;
  Content: React.ComponentType<
    TProps & {
      resource: ViewerResource;
      retryVersion: number;
      forwardedRef?: React.ForwardedRef<THandle>;
    }
  >;
}

export interface PlainTextViewerFramePublicProps extends TextViewerBounds {
  source?: TextResourceSource;
  className?: string;
  controls?: boolean;
  download?: boolean;
  bare?: boolean;
}

export interface PlainTextViewerFallbackProps {
  className?: string;
  controls?: boolean;
  download?: boolean;
  bare?: boolean;
}

export function PlainTextViewerFrame<
  THandle,
  TProps extends PlainTextViewerFramePublicProps,
>({
  props,
  resource: resourceProp,
  forwardedRef,
  clientFallbackPolicy,
  contentResetPolicy = "content",
  Fallback,
  Content,
}: PlainTextViewerFrameProps<THandle, TProps>) {
  const [retryState, setRetryState] = React.useState({
    contentKey: "",
    version: 0,
  });
  const isClient = useIsClient();
  const { source } = props;
  const createdResource = React.useMemo(
    () => (source ? createViewerResource(source) : null),
    [source],
  );
  const resource = resourceProp ?? createdResource;
  if (!resource) {
    throw new Error("PlainTextViewerFrame requires a source or resource.");
  }
  const contentBaseKey = plainTextViewerContentBaseKey(resource, props);
  const retryVersion =
    retryState.contentKey === contentBaseKey ? retryState.version : 0;
  const resetKey = plainTextViewerResetKey(resource, props, retryVersion);
  const contentResetKey = plainTextViewerContentResetKey(
    contentBaseKey,
    retryVersion,
  );
  const suspenseResetKey =
    contentResetPolicy === "inline-retry" && resource.sourceKind === "text"
      ? String(retryVersion)
      : contentResetKey;

  if (
    !isClient &&
    shouldRenderClientFallback(clientFallbackPolicy, resource.sourceKind)
  ) {
    return (
      <Fallback
        className={props.className}
        controls={props.controls}
        download={props.download}
        bare={props.bare}
      />
    );
  }

  return (
    <ViewerErrorBoundary
      bare={props.bare}
      className={props.className}
      download={
        props.controls === false || props.download === false
          ? null
          : plainTextViewerDownloadAction(resource)
      }
      format="text"
      mapError={plainTextViewerBoundaryError}
      resetKey={resetKey}
      sourceKind={resource.sourceKind}
      onRetry={() =>
        setRetryState((state) => ({
          contentKey: contentBaseKey,
          version: state.contentKey === contentBaseKey ? state.version + 1 : 1,
        }))
      }
    >
      <React.Suspense
        key={suspenseResetKey}
        fallback={
          <Fallback
            className={props.className}
            controls={props.controls}
            download={props.download}
            bare={props.bare}
          />
        }
      >
        <Content
          {...props}
          forwardedRef={forwardedRef}
          retryVersion={retryVersion}
          resource={resource}
        />
      </React.Suspense>
    </ViewerErrorBoundary>
  );
}

function plainTextViewerDownloadAction(resource: ViewerResource) {
  return resource.originalDownload;
}

function plainTextViewerBoundaryError(error: unknown) {
  if (
    isResourceError(error) ||
    isViewerFormatError(error) ||
    isViewerStateError(error) ||
    isViewerUnsupportedError(error)
  ) {
    return error;
  }

  return new ViewerFormatError({
    format: "text",
    kind: "render_failed",
    message: "Failed to render text.",
    cause: error,
  });
}

function plainTextViewerResetKey(
  resource: ViewerResource,
  props: Pick<PlainTextViewerFramePublicProps, "maxBytes" | "maxLines">,
  retryVersion: number,
): string {
  const [maxBytesKey, maxLinesKey] = plainTextViewerBoundsResetKey(props);
  return [
    viewerResourceRenderKey(resource),
    retryVersion,
    maxBytesKey,
    maxLinesKey,
  ].join("\u0000");
}

function plainTextViewerContentResetKey(
  contentBaseKey: string,
  retryVersion: number,
): string {
  return [contentBaseKey, retryVersion].join("\u0000");
}

function plainTextViewerContentBaseKey(
  resource: ViewerResource,
  props: Pick<PlainTextViewerFramePublicProps, "maxBytes" | "maxLines">,
): string {
  const [maxBytesKey, maxLinesKey] = plainTextViewerBoundsResetKey(props);
  return [
    viewerContentRenderKey(resource.content),
    maxBytesKey,
    maxLinesKey,
  ].join("\u0000");
}

function plainTextViewerBoundsResetKey(
  props: Pick<PlainTextViewerFramePublicProps, "maxBytes" | "maxLines">,
) {
  return [
    plainTextViewerBoundResetKeyPart(props.maxBytes, DEFAULT_MAX_BYTES),
    plainTextViewerBoundResetKeyPart(props.maxLines, DEFAULT_MAX_LINES),
  ] as const;
}

function plainTextViewerBoundResetKeyPart(
  value: number | undefined,
  defaultValue: number,
) {
  return String(value === undefined ? defaultValue : value);
}

function shouldRenderClientFallback(
  policy: ClientFallbackPolicy,
  sourceKind: TextResourceSource["kind"],
) {
  return policy === "always" || sourceKind !== "text";
}

"use client";

import * as React from "react";

import { useKeyedLayoutEffect } from "@/hooks/use-keyed-layout-effect";
import { useKeyedMountEffect } from "@/hooks/use-keyed-mount-effect";
import { useMountEffect } from "@/hooks/use-mount-effect";
import type { ViewerResource } from "@/lib/viewer-resource";

import {
  CodeViewerControls,
  codeViewerControlsState,
  CodeViewerFrame,
} from "./code-viewer-chrome";
import { scrollTopForLineRangeMetrics } from "./code-viewer-layout";
import { getCodeLongLineSelectionText } from "./code-viewer-long-lines";
import { useCodeProjectionScheduler } from "./code-viewer-projection-scheduler";
import { createCodeProjector } from "./code-viewer-projector";
import {
  clampCodeViewerScale,
  CODE_VIEWER_BASE_LINE_PX,
  CODE_VIEWER_BLOCK_PADDING,
} from "./code-viewer-scale";
import { createCodeSyntax } from "./code-viewer-syntax";
import { useCodeViewerSyntaxStyle } from "./code-viewer-syntax-style";
import type {
  CodeLineRange,
  CodeViewerHandle,
  CodeViewerProps,
} from "./code-viewer-types";
import { CodeViewerViewport } from "./code-viewer-viewport";
import { normalizeTextLineRange } from "./line-ranges";
import {
  readTextDocument,
  resolvedTextViewerBounds,
} from "./plain-text-resource";
import { useViewerControlsRegistration } from "./viewer-controls";
import { joinEffectKey } from "@/lib/effect-key";

type CodeReadingAnchor = {
  lineIndex: number;
  offsetPx: number;
};

type NativeFindCodeChunk = {
  endLine: number;
  startLine: number;
  text: string;
};

type CodeIdleWindow = Window &
  typeof globalThis & {
    cancelIdleCallback?: Window["cancelIdleCallback"];
    requestIdleCallback?: Window["requestIdleCallback"];
  };

const CODE_VIEWER_DEFERRED_SYNTAX_LINE_COUNT = 500;
const CODE_VIEWER_NATIVE_FIND_CHUNK_SIZE = 128;

type CodeViewerContentProps = Omit<CodeViewerProps, "source"> & {
  resource: ViewerResource;
  retryVersion: number;
  forwardedRef?: React.ForwardedRef<CodeViewerHandle>;
};

export function CodeViewerContent({
  resource,
  className,
  controls = true,
  download = true,
  highlight,
  bare = false,
  maxBytes,
  maxLines,
  retryVersion,
  forwardedRef,
}: CodeViewerContentProps) {
  const bounds = resolvedTextViewerBounds({ maxBytes, maxLines });
  const textDocument = readTextDocument({
    content: resource.content,
    retryVersion,
    bounds,
  });
  const textLines = textDocument.lines;
  const [syntaxVersion, setSyntaxVersion] = React.useState(0);
  const syntax = React.useMemo(
    () =>
      createCodeSyntax(resource, {
        deferTokens: textLines.length > CODE_VIEWER_DEFERRED_SYNTAX_LINE_COUNT,
        onTokensChanged: () => setSyntaxVersion((version) => version + 1),
      }),
    [resource, textLines.length],
  );
  const syntaxIdentity =
    syntaxVersion === 0
      ? syntax.identity
      : `${syntax.identity}\u0000${syntaxVersion}`;
  const highlightStart = highlight?.start;
  const highlightEnd = highlight?.end;
  const highlightRange = React.useMemo(
    () =>
      normalizeTextLineRange(
        highlightStart == null || highlightEnd == null
          ? null
          : { start: highlightStart, end: highlightEnd },
        textLines.length,
      ),
    [highlightStart, highlightEnd, textLines.length],
  );
  const downloadAction = download ? resource.originalDownload : null;

  const [fontScale, setFontScale] = React.useState(1);
  const viewportRef = React.useRef<HTMLDivElement | null>(null);
  const rowHostRef = React.useRef<HTMLPreElement | null>(null);
  const pendingScrollAnchorRef = React.useRef<CodeReadingAnchor | null>(null);
  const projector = React.useMemo(() => createCodeProjector(), []);
  const lineHeight = CODE_VIEWER_BASE_LINE_PX * fontScale;
  const contentIdentity = React.useMemo(
    () =>
      codeContentIdentity({
        contentKey: resource.content.key,
        maxBytes: bounds.maxBytes,
        maxLines: bounds.maxLines,
        retryVersion,
      }),
    [bounds.maxBytes, bounds.maxLines, resource.content.key, retryVersion],
  );
  const gutterWidth = `calc(${String(textLines.length).length + 1}ch + 1.25rem)`;
  const layoutIdentity = codeLayoutIdentity({ gutterWidth, lineHeight });

  useCodeViewerSyntaxStyle();

  const commitFontScale = React.useCallback(
    (nextScale: number) => {
      const clampedScale = clampCodeViewerScale(nextScale);
      if (clampedScale === fontScale) return;

      pendingScrollAnchorRef.current = captureCodeReadingAnchor({
        lineCount: textLines.length,
        lineHeight,
        projector,
        viewportElement: viewportRef.current,
      });
      setFontScale(clampedScale);
    },
    [fontScale, lineHeight, projector, textLines.length],
  );

  const zoom = React.useCallback(
    (factor: number) => commitFontScale(fontScale * factor),
    [commitFontScale, fontScale],
  );
  const onZoomOut = React.useCallback(() => zoom(1 / 1.2), [zoom]);
  const onZoomIn = React.useCallback(() => zoom(1.2), [zoom]);
  const onResetZoom = React.useCallback(
    () => commitFontScale(1),
    [commitFontScale],
  );

  useKeyedMountEffect(
    joinEffectKey(["code-anchor", lineHeight, textLines.length]),
    () => {
      const anchor = pendingScrollAnchorRef.current;
      const viewportElement = viewportRef.current;
      if (!anchor || !viewportElement) return;

      pendingScrollAnchorRef.current = null;
      projector.scrollToLogical({
        lineCount: textLines.length,
        lineHeight,
        logicalScrollTop: restoreCodeReadingAnchor({
          anchor,
          lineCount: textLines.length,
          lineHeight,
        }),
        viewport: viewportElement,
      });
    },
  );

  const scrollLineRange = React.useCallback(
    (range: CodeLineRange | null, options?: ScrollToOptions) => {
      const viewportElement = viewportRef.current;
      const normalizedRange = normalizeTextLineRange(range, textLines.length);
      if (!viewportElement || !normalizedRange) return;

      projector.scrollToLogical({
        behavior: options?.behavior ?? "smooth",
        lineCount: textLines.length,
        lineHeight,
        logicalScrollTop: scrollTopForLineRangeMetrics({
          startLine: normalizedRange.start,
          endLine: normalizedRange.end,
          lineHeight,
          paddingStart: CODE_VIEWER_BLOCK_PADDING,
          viewportHeight: viewportElement.clientHeight,
        }),
        viewport: viewportElement,
      });
    },
    [lineHeight, projector, textLines.length],
  );

  React.useImperativeHandle(
    forwardedRef ?? null,
    () => ({
      scrollToLineRange: scrollLineRange,
      getViewportElement: () => viewportRef.current,
    }),
    [scrollLineRange],
  );

  useKeyedMountEffect(
    joinEffectKey(["code-highlight-scroll", highlightRange, scrollLineRange]),
    () => {
      if (!highlightRange) return;
      scrollLineRange(highlightRange, { behavior: "smooth" });
    },
  );

  const project = React.useCallback(() => {
    const rowHost = rowHostRef.current;
    const viewport = viewportRef.current;
    if (!rowHost || !viewport) return false;

    return projector.project({
      contentIdentity,
      gutterWidth,
      highlightRange,
      layoutIdentity,
      lineHeight,
      rowHost,
      syntax,
      syntaxIdentity,
      textLines,
      viewport,
    });
  }, [
    contentIdentity,
    gutterWidth,
    highlightRange,
    layoutIdentity,
    lineHeight,
    projector,
    syntax,
    syntaxIdentity,
    textLines,
  ]);

  const copyLongLineSelection = React.useCallback(
    (event: React.ClipboardEvent<HTMLPreElement>) => {
      const rowHost = rowHostRef.current;
      if (!rowHost) return;

      const selectedText = getCodeLongLineSelectionText({
        rowHost,
        selection: window.getSelection(),
        textLines,
      });
      if (selectedText == null) return;

      event.clipboardData.setData("text/plain", selectedText);
      event.preventDefault();
    },
    [textLines],
  );

  useCodeProjectionScheduler({
    project,
    rowHostRef,
    viewportRef,
  });

  useMountEffect(() => () => projector.destroy());
  useKeyedMountEffect(joinEffectKey(["code-syntax", syntax]), () => {
    setSyntaxVersion(0);
    return () => syntax.destroy?.();
  });

  useCodeControlsRegistration({
    downloadAction,
    fontScale,
    lineCount: textLines.length,
    onResetZoom,
    onZoomIn,
    onZoomOut,
  });

  return (
    <CodeViewerFrame className={className} bare={bare}>
      {controls ? (
        <CodeViewerControls
          lineCount={textLines.length}
          fontScale={fontScale}
          downloadAction={downloadAction}
          onZoomOut={onZoomOut}
          onZoomIn={onZoomIn}
          onResetZoom={onResetZoom}
        />
      ) : null}
      <DeferredNativeFindIndex
        lineCount={textLines.length}
        lines={textLines}
        scrollToLineRange={scrollLineRange}
      />
      <CodeViewerViewport
        fontScale={fontScale}
        gutterWidth={gutterWidth}
        lineCount={textLines.length}
        lineHeight={lineHeight}
        onCopy={copyLongLineSelection}
        rowHostRef={rowHostRef}
        viewportRef={viewportRef}
      />
    </CodeViewerFrame>
  );
}

function DeferredNativeFindIndex({
  lines,
  lineCount,
  scrollToLineRange,
}: {
  lines: readonly string[];
  lineCount: number;
  scrollToLineRange: (
    range: CodeLineRange | null,
    options?: ScrollToOptions,
  ) => void;
}) {
  const [isReady, setIsReady] = React.useState(false);

  useKeyedMountEffect(joinEffectKey(["code-native-find", lines]), () => {
    setIsReady(false);
    const show = () => setIsReady(true);
    if (typeof window === "undefined") return;
    const browserWindow = window as CodeIdleWindow;
    if (browserWindow.requestIdleCallback && browserWindow.cancelIdleCallback) {
      const idleId = browserWindow.requestIdleCallback(show, { timeout: 400 });
      return () => browserWindow.cancelIdleCallback?.(idleId);
    }
    const timeoutId = browserWindow.setTimeout(show, 80);
    return () => browserWindow.clearTimeout(timeoutId);
  });

  if (!isReady) return null;
  return (
    <NativeFindIndex
      lineCount={lineCount}
      lines={lines}
      scrollToLineRange={scrollToLineRange}
    />
  );
}

function NativeFindIndex({
  lines,
  lineCount,
  scrollToLineRange,
}: {
  lines: readonly string[];
  lineCount: number;
  scrollToLineRange: (
    range: CodeLineRange | null,
    options?: ScrollToOptions,
  ) => void;
}) {
  const entries = React.useMemo(() => chunkNativeFindLines(lines), [lines]);

  return (
    <div
      aria-hidden="true"
      className="pointer-events-none h-0 w-0 overflow-hidden opacity-0"
      data-native-find-indexed-chunks={entries.length}
      data-native-find-indexed-lines={lines.length}
      data-slot="code-native-find-index"
    >
      {entries.map((entry) => (
        <NativeFindEntry
          key={entry.startLine}
          entry={entry}
          lineCount={lineCount}
          scrollToLineRange={scrollToLineRange}
        />
      ))}
    </div>
  );
}

function NativeFindEntry({
  entry,
  lineCount,
  scrollToLineRange,
}: {
  entry: NativeFindCodeChunk;
  lineCount: number;
  scrollToLineRange: (
    range: CodeLineRange | null,
    options?: ScrollToOptions,
  ) => void;
}) {
  const ref = React.useRef<HTMLSpanElement | null>(null);

  useKeyedLayoutEffect(
    joinEffectKey([
      "code-native-find-entry",
      entry.startLine,
      entry.endLine,
      lineCount,
      scrollToLineRange,
    ]),
    () => {
      const element = ref.current;
      if (!element) return;
      element.setAttribute("hidden", "until-found");

      const handleBeforeMatch = () => {
        scrollToLineRange(
          normalizeTextLineRange(
            {
              end: entry.endLine,
              start: entry.startLine,
            },
            lineCount,
          ),
          { behavior: "auto" },
        );
        if (typeof requestAnimationFrame === "function") {
          requestAnimationFrame(() => {
            element.setAttribute("hidden", "until-found");
          });
          return;
        }
        element.setAttribute("hidden", "until-found");
      };

      element.addEventListener("beforematch", handleBeforeMatch);
      return () => {
        element.removeEventListener("beforematch", handleBeforeMatch);
      };
    },
  );

  return (
    <span
      ref={ref}
      className="block h-px w-px overflow-hidden whitespace-pre"
      data-native-find-end-line={entry.endLine}
      data-native-find-start-line={entry.startLine}
    >
      {entry.text || " "}
    </span>
  );
}

function chunkNativeFindLines(lines: readonly string[]): NativeFindCodeChunk[] {
  const chunks: NativeFindCodeChunk[] = [];
  for (
    let startIndex = 0;
    startIndex < lines.length;
    startIndex += CODE_VIEWER_NATIVE_FIND_CHUNK_SIZE
  ) {
    const endIndex = Math.min(
      lines.length,
      startIndex + CODE_VIEWER_NATIVE_FIND_CHUNK_SIZE,
    );
    chunks.push({
      endLine: endIndex,
      startLine: startIndex + 1,
      text: lines.slice(startIndex, endIndex).join("\n"),
    });
  }
  return chunks;
}

function useCodeControlsRegistration({
  downloadAction,
  fontScale,
  lineCount,
  onResetZoom,
  onZoomIn,
  onZoomOut,
}: {
  downloadAction: ViewerResource["originalDownload"] | null;
  fontScale: number;
  lineCount: number;
  onResetZoom: () => void;
  onZoomIn: () => void;
  onZoomOut: () => void;
}) {
  const onControlsChange = useViewerControlsRegistration();
  const controlsState = React.useMemo(
    () =>
      codeViewerControlsState({
        downloadAction,
        fontScale,
        lineCount,
        onResetZoom,
        onZoomIn,
        onZoomOut,
      }),
    [downloadAction, fontScale, lineCount, onResetZoom, onZoomIn, onZoomOut],
  );

  useKeyedMountEffect(
    joinEffectKey(["code-controls", onControlsChange, controlsState]),
    () => {
      if (!onControlsChange) return;
      onControlsChange(controlsState);
      return () => onControlsChange(null);
    },
  );
}

function captureCodeReadingAnchor({
  lineCount,
  lineHeight,
  projector,
  viewportElement,
}: {
  lineCount: number;
  lineHeight: number;
  projector: ReturnType<typeof createCodeProjector>;
  viewportElement: HTMLDivElement | null;
}): CodeReadingAnchor | null {
  if (!viewportElement || lineCount <= 0 || lineHeight <= 0) return null;

  const scrollTop = projector.getLogicalScrollTop({
    lineCount,
    lineHeight,
    viewport: viewportElement,
  });
  const contentTop = Math.max(0, scrollTop - CODE_VIEWER_BLOCK_PADDING);
  const lineIndex = Math.min(
    lineCount - 1,
    Math.max(0, Math.floor(contentTop / lineHeight)),
  );

  return {
    lineIndex,
    offsetPx: Math.max(0, contentTop - lineIndex * lineHeight),
  };
}

function restoreCodeReadingAnchor({
  anchor,
  lineCount,
  lineHeight,
}: {
  anchor: CodeReadingAnchor;
  lineCount: number;
  lineHeight: number;
}) {
  if (lineCount <= 0 || lineHeight <= 0) return 0;

  const lineIndex = Math.min(lineCount - 1, Math.max(0, anchor.lineIndex));
  return (
    CODE_VIEWER_BLOCK_PADDING +
    lineIndex * lineHeight +
    Math.min(anchor.offsetPx, Math.max(0, lineHeight - 1))
  );
}

function codeContentIdentity({
  contentKey,
  maxBytes,
  maxLines,
  retryVersion,
}: {
  contentKey: string;
  maxBytes: number;
  maxLines: number;
  retryVersion: number;
}) {
  return [contentKey, retryVersion, maxBytes, maxLines].join("\u0000");
}

function codeLayoutIdentity({
  gutterWidth,
  lineHeight,
}: {
  gutterWidth: string;
  lineHeight: number;
}) {
  return [lineHeight, gutterWidth].join("\u0000");
}

import {
  CODE_VIEWER_BLOCK_PADDING,
  CODE_VIEWER_INITIAL_VIEWPORT_HEIGHT,
  CODE_VIEWER_OVERSCAN_PX,
} from "./code-viewer-scale";
import type { CodeSyntax, CodeTokenLeaf } from "./code-viewer-syntax";
import {
  getCodeLogicalScrollTop,
  getCodePagedLayoutTop,
  getCodePhysicalScrollSize,
  getCodeVirtualLineWindow,
  getCodeVirtualTotalSize,
  resolveCodePhysicalScrollPosition,
  type CodeVirtualLine,
} from "./code-viewer-virtualization";
import { getCodeLineRenderText } from "./code-viewer-long-lines";
import { isLineInRange, type NormalizedTextLineRange } from "./line-ranges";

// Opaque fills mixed from the theme's opaque `--foreground`/`--background`
// tokens (the `--muted`/`--accent` tokens are alpha-based, so they cannot mask
// scrolled content). Shared with the viewport's full-height gutter rail.
export const CODE_GUTTER_BACKGROUND =
  "color-mix(in oklab, var(--foreground) 3%, var(--background))";
const CODE_HIGHLIGHT_BACKGROUND =
  "color-mix(in oklab, var(--foreground) 8%, var(--background))";
const CODE_HIGHLIGHT_ACCENT_SHADOW = "inset 2px 0 0 0 var(--primary)";
const CODE_HIGHLIGHT_NUMBER_COLOR =
  "color-mix(in oklab, var(--foreground) 70%, transparent)";

export type CodeProjectionIdentity = {
  contentIdentity: string;
  layoutIdentity: string;
  syntaxIdentity: string;
};

export type CodeProjectionInput = CodeProjectionIdentity & {
  rowHost: HTMLPreElement;
  viewport: HTMLDivElement;
  textLines: readonly string[];
  lineHeight: number;
  gutterWidth: string;
  highlightRange: NormalizedTextLineRange | null;
  syntax: CodeSyntax;
};

export type CodeProjector = {
  getLogicalScrollTop(input: CodeProjectionScrollInput): number;
  project(input: CodeProjectionInput): boolean;
  scrollToLogical(input: CodeProjectionScrollToInput): void;
  destroy(): void;
};

export type CodeProjectionScrollInput = {
  lineCount: number;
  lineHeight: number;
  viewport: HTMLDivElement;
};

export type CodeProjectionScrollToInput = CodeProjectionScrollInput & {
  behavior?: ScrollBehavior;
  logicalScrollTop: number;
};

export type CodeProjectionMetrics = {
  contentPatches: number;
  layoutPatches: number;
  noops: number;
  projections: number;
  rowsCreated: number;
  rowsRemoved: number;
  rowsReused: number;
  tokenSpanRebuilds: number;
  visibleEnd: number;
  visibleStart: number;
};

export type CodeProjectorOptions = {
  metrics?: CodeProjectionMetrics;
};

type CodeRowCache = {
  contentIdentity: string;
  contentSpan: HTMLSpanElement;
  gutterSpan: HTMLSpanElement;
  layoutIdentity: string;
  row: HTMLDivElement;
};

type VisibleRange = {
  end: number;
  start: number;
};

type LastProjection = CodeProjectionIdentity & {
  highlightIdentity: string;
  horizontalScrollLeft: number;
  renderedWindowHeight: number;
  renderedWindowStickyOffset: number;
  renderedWindowTop: number;
  logicalScrollTop: number;
  scrollPageOffset: number;
  totalHeight: string;
  visibleEnd: number;
  visibleStart: number;
};

type CodeRenderedWindow = {
  height: number;
  rowOffset: number;
  stickyOffset: number;
  top: number;
};

const MAX_RECYCLED_CODE_ROWS = 512;

export function createCodeProjectionMetrics(): CodeProjectionMetrics {
  return {
    contentPatches: 0,
    layoutPatches: 0,
    noops: 0,
    projections: 0,
    rowsCreated: 0,
    rowsRemoved: 0,
    rowsReused: 0,
    tokenSpanRebuilds: 0,
    visibleEnd: 0,
    visibleStart: 0,
  };
}

export function createCodeProjector(
  options: CodeProjectorOptions = {},
): CodeProjector {
  let identity: CodeProjectionIdentity | null = null;
  let lastProjection: LastProjection | null = null;
  let metrics = options.metrics;
  let rowHost: HTMLPreElement | null = null;
  let recycledRows: CodeRowCache[] = [];
  const rowsByLineIndex = new Map<number, CodeRowCache>();
  let scrollPageOffset = 0;
  let visibleRange: VisibleRange | null = null;

  return {
    getLogicalScrollTop(input) {
      return getCodeLogicalScrollTop({
        physicalScrollTop: input.viewport.scrollTop,
        scrollPageOffset,
        totalSize: codeTotalSize(input),
        viewportHeight: codeViewportHeight(input.viewport),
      });
    },
    project(input) {
      metrics = options.metrics;
      incrementMetric(metrics, "projections");

      if (rowHost !== input.rowHost) {
        clearRows();
        rowHost = input.rowHost;
      }

      const nextIdentity = codeProjectionIdentity(input);
      if (
        !identity ||
        identity.contentIdentity !== nextIdentity.contentIdentity
      ) {
        identity = nextIdentity;
        clearRows();
      } else {
        identity = nextIdentity;
      }

      const totalSize = codeTotalSize({
        lineCount: input.textLines.length,
        lineHeight: input.lineHeight,
        viewport: input.viewport,
      });
      const viewportHeight = codeViewportHeight(input.viewport);
      const previousProjection = lastProjection;
      const logicalScrollTop = getCodeLogicalScrollTop({
        physicalScrollTop: input.viewport.scrollTop,
        scrollPageOffset,
        totalSize,
        viewportHeight,
      });
      const physicalScrollPosition = resolveCodePhysicalScrollPosition({
        logicalScrollTop,
        scrollPageOffset,
        totalSize,
        viewportHeight,
      });
      const previousScrollPageOffset = scrollPageOffset;
      scrollPageOffset = physicalScrollPosition.scrollPageOffset;

      if (
        physicalScrollPosition.physicalScrollTop !== input.viewport.scrollTop
      ) {
        input.viewport.scrollTop = physicalScrollPosition.physicalScrollTop;
      }

      const physicalTotalSize = getCodePhysicalScrollSize({
        totalSize,
        viewportHeight,
      });
      const totalHeight = `${physicalTotalSize}px`;
      const fitPerfectly = shouldFitCodePerfectly({
        previousProjection,
        logicalScrollTop,
        viewportHeight,
      });

      const virtualWindow = getCodeVirtualLineWindow({
        lineCount: input.textLines.length,
        lineHeight: input.lineHeight,
        overscanPx: fitPerfectly
          ? getCodeFitPerfectlyOverscanPx(input.lineHeight)
          : CODE_VIEWER_OVERSCAN_PX,
        paddingStart: CODE_VIEWER_BLOCK_PADDING,
        scrollTop: logicalScrollTop,
        viewportHeight,
      });
      const visibleLines = virtualWindow.lines;
      const renderedWindow = codeRenderedWindow({
        physicalTotalSize,
        rowHost: input.rowHost,
        scrollPageOffset,
        totalSize,
        viewportHeight,
        visibleLines,
      });
      const nextVisibleRange = codeVisibleRange(visibleLines);
      const nextProjection = codeLastProjection({
        input,
        logicalScrollTop,
        renderedWindow,
        scrollPageOffset,
        totalHeight,
        visibleRange: nextVisibleRange,
      });
      if (
        lastProjection &&
        isSameCodeProjection(lastProjection, nextProjection) &&
        isRenderedDomValid(nextVisibleRange)
      ) {
        incrementMetric(metrics, "noops");
        return false;
      }
      lastProjection = nextProjection;
      setMetric(metrics, "visibleStart", nextVisibleRange.start);
      setMetric(metrics, "visibleEnd", nextVisibleRange.end);

      syncCodeScrollLayers({
        renderedWindow,
        rowHost: input.rowHost,
        totalHeight,
      });

      syncVisibleRows({
        input,
        nextVisibleRange,
        previousScrollPageOffset,
        renderedWindow,
        totalSize,
        viewportHeight,
        visibleLines,
      });
      visibleRange = nextVisibleRange;
      return fitPerfectly;
    },
    scrollToLogical(input) {
      const totalSize = codeTotalSize(input);
      const viewportHeight = codeViewportHeight(input.viewport);
      const physicalScrollPosition = resolveCodePhysicalScrollPosition({
        logicalScrollTop: input.logicalScrollTop,
        scrollPageOffset,
        totalSize,
        viewportHeight,
      });
      scrollPageOffset = physicalScrollPosition.scrollPageOffset;
      if (typeof input.viewport.scrollTo === "function") {
        input.viewport.scrollTo({
          top: physicalScrollPosition.physicalScrollTop,
          behavior: input.behavior,
        });
      } else {
        input.viewport.scrollTop = physicalScrollPosition.physicalScrollTop;
      }
    },
    destroy() {
      clearRows();
      recycledRows = [];
      rowHost = null;
      identity = null;
      scrollPageOffset = 0;
    },
  };

  function syncVisibleRows({
    input,
    nextVisibleRange,
    previousScrollPageOffset,
    renderedWindow,
    totalSize,
    viewportHeight,
    visibleLines,
  }: {
    input: CodeProjectionInput;
    nextVisibleRange: VisibleRange;
    previousScrollPageOffset: number;
    renderedWindow: CodeRenderedWindow;
    totalSize: number;
    viewportHeight: number;
    visibleLines: readonly CodeVirtualLine[];
  }) {
    if (
      previousScrollPageOffset === scrollPageOffset &&
      applyPartialRender({
        input,
        nextVisibleRange,
        renderedWindow,
        totalSize,
        viewportHeight,
        visibleLines,
      })
    ) {
      return;
    }

    clearMountedRows();
    syncVisibleRowOrder({
      input,
      renderedWindow,
      totalSize,
      viewportHeight,
      visibleLines,
    });
  }

  function syncVisibleRowOrder({
    input,
    renderedWindow,
    totalSize,
    viewportHeight,
    visibleLines,
  }: {
    input: CodeProjectionInput;
    renderedWindow: CodeRenderedWindow;
    totalSize: number;
    viewportHeight: number;
    visibleLines: readonly CodeVirtualLine[];
  }) {
    let cursor = input.rowHost.firstChild;

    for (const visibleLine of visibleLines) {
      const row = prepareCodeRow({
        input,
        renderedWindow,
        totalSize,
        viewportHeight,
        visibleLine,
      });
      if (row !== cursor) {
        input.rowHost.insertBefore(row, cursor);
      }
      cursor = row.nextSibling;
    }

    while (cursor) {
      const nextCursor = cursor.nextSibling;
      cursor.parentNode?.removeChild(cursor);
      cursor = nextCursor;
    }
  }

  function applyPartialRender({
    input,
    nextVisibleRange,
    renderedWindow,
    totalSize,
    viewportHeight,
    visibleLines,
  }: {
    input: CodeProjectionInput;
    nextVisibleRange: VisibleRange;
    renderedWindow: CodeRenderedWindow;
    totalSize: number;
    viewportHeight: number;
    visibleLines: readonly CodeVirtualLine[];
  }): boolean {
    const previousRange = visibleRange;
    if (!previousRange) return false;
    if (!isRenderedDomValid(previousRange)) return false;

    const overlapStart = Math.max(previousRange.start, nextVisibleRange.start);
    const overlapEnd = Math.min(previousRange.end, nextVisibleRange.end);
    if (overlapStart >= overlapEnd) {
      return false;
    }

    removeCodeRowRange(previousRange.start, overlapStart);
    removeCodeRowRange(overlapEnd, previousRange.end);

    syncVisibleRowOrder({
      input,
      renderedWindow,
      totalSize,
      viewportHeight,
      visibleLines,
    });
    return true;
  }

  function clearRows() {
    for (const row of rowsByLineIndex.values()) {
      recycleCodeRow(row);
    }
    rowHost?.replaceChildren();
    rowsByLineIndex.clear();
    lastProjection = null;
    visibleRange = null;
  }

  function clearMountedRows() {
    if (!visibleRange) return;
    removeCodeRowRange(visibleRange.start, visibleRange.end);
    visibleRange = null;
  }

  function removeCodeRowRange(start: number, end: number) {
    for (
      let index = Math.max(0, start);
      index < Math.max(start, end);
      index++
    ) {
      const row = rowsByLineIndex.get(index);
      if (!row) continue;
      row.row.remove();
      incrementMetric(metrics, "rowsRemoved");
      recycleCodeRow(row);
      rowsByLineIndex.delete(index);
    }
  }

  function isRenderedDomValid(range: VisibleRange) {
    if (!rowHost) return false;
    const expectedLength = Math.max(0, range.end - range.start);
    if (rowHost.children.length !== expectedLength) return false;

    for (let offset = 0; offset < expectedLength; offset += 1) {
      const index = range.start + offset;
      const element = rowHost.children[offset];
      const row = rowsByLineIndex.get(index);
      if (!(element instanceof HTMLDivElement) || row?.row !== element) {
        return false;
      }
      if (element.dataset.lineIndex !== String(index)) {
        return false;
      }
    }
    return true;
  }

  function recycleCodeRow(row: CodeRowCache) {
    row.contentIdentity = "";
    row.layoutIdentity = "";
    if (recycledRows.length < MAX_RECYCLED_CODE_ROWS) {
      recycledRows.push(row);
    }
  }

  function prepareCodeRow({
    input,
    renderedWindow,
    totalSize,
    viewportHeight,
    visibleLine,
  }: {
    input: CodeProjectionInput;
    renderedWindow: CodeRenderedWindow;
    totalSize: number;
    viewportHeight: number;
    visibleLine: CodeVirtualLine;
  }): HTMLDivElement {
    const lineNumber = visibleLine.index + 1;
    const text = input.textLines[visibleLine.index] ?? "";
    const isHighlighted = isLineInRange(lineNumber, input.highlightRange);
    const layoutIdentity = [
      lineNumber,
      input.layoutIdentity,
      isHighlighted ? "highlighted" : "",
    ].join("\u0000");
    const contentIdentity = codeRowContentIdentity({
      syntax: input.syntax,
      text,
    });

    let row = rowsByLineIndex.get(visibleLine.index);
    if (!row) {
      row = recycledRows.pop();
      if (row) {
        incrementMetric(metrics, "rowsReused");
      } else {
        row = createCodeRow();
        incrementMetric(metrics, "rowsCreated");
      }
      rowsByLineIndex.set(visibleLine.index, row);
    }

    setStyleValue(row.row.style, "height", `${visibleLine.size}px`);
    setStyleValue(
      row.row.style,
      "transform",
      `translateY(${
        getCodePagedLayoutTop({
          logicalTop: visibleLine.start,
          scrollPageOffset,
          totalSize,
          viewportHeight,
        }) - renderedWindow.rowOffset
      }px)`,
    );

    if (row.layoutIdentity !== layoutIdentity) {
      row.layoutIdentity = layoutIdentity;
      patchCodeRowLayout({
        gutterWidth: input.gutterWidth,
        isHighlighted,
        metrics,
        lineNumber,
        row,
      });
    }

    if (row.contentIdentity !== contentIdentity) {
      row.contentIdentity = contentIdentity;
      patchCodeRowContent({
        metrics,
        row,
        syntax: input.syntax,
        text,
      });
    }

    return row.row;
  }
}

function codeLastProjection({
  input,
  logicalScrollTop,
  renderedWindow,
  scrollPageOffset,
  totalHeight,
  visibleRange,
}: {
  input: CodeProjectionInput;
  logicalScrollTop: number;
  renderedWindow: CodeRenderedWindow;
  scrollPageOffset: number;
  totalHeight: string;
  visibleRange: VisibleRange;
}): LastProjection {
  return {
    contentIdentity: input.contentIdentity,
    highlightIdentity: codeHighlightIdentity(input.highlightRange),
    horizontalScrollLeft: input.viewport.scrollLeft,
    layoutIdentity: input.layoutIdentity,
    logicalScrollTop,
    renderedWindowHeight: renderedWindow.height,
    renderedWindowStickyOffset: renderedWindow.stickyOffset,
    renderedWindowTop: renderedWindow.top,
    scrollPageOffset,
    syntaxIdentity: input.syntaxIdentity,
    totalHeight,
    visibleEnd: visibleRange.end,
    visibleStart: visibleRange.start,
  };
}

function codeHighlightIdentity(range: NormalizedTextLineRange | null) {
  return range ? `${range.start}:${range.end}` : "";
}

function isSameCodeProjection(previous: LastProjection, next: LastProjection) {
  return (
    previous.contentIdentity === next.contentIdentity &&
    previous.highlightIdentity === next.highlightIdentity &&
    previous.horizontalScrollLeft === next.horizontalScrollLeft &&
    previous.layoutIdentity === next.layoutIdentity &&
    previous.renderedWindowHeight === next.renderedWindowHeight &&
    previous.renderedWindowStickyOffset === next.renderedWindowStickyOffset &&
    previous.renderedWindowTop === next.renderedWindowTop &&
    previous.scrollPageOffset === next.scrollPageOffset &&
    previous.syntaxIdentity === next.syntaxIdentity &&
    previous.totalHeight === next.totalHeight &&
    previous.visibleEnd === next.visibleEnd &&
    previous.visibleStart === next.visibleStart
  );
}

function codeProjectionIdentity({
  contentIdentity,
  layoutIdentity,
  syntaxIdentity,
}: CodeProjectionIdentity): CodeProjectionIdentity {
  return {
    contentIdentity,
    layoutIdentity,
    syntaxIdentity,
  };
}

function codeVisibleRange(
  visibleLines: readonly CodeVirtualLine[],
): VisibleRange {
  const start = visibleLines[0]?.index ?? 0;
  const end = visibleLines.length
    ? visibleLines[visibleLines.length - 1]!.index + 1
    : start;
  return { end, start };
}

function codeTotalSize({
  lineCount,
  lineHeight,
}: {
  lineCount: number;
  lineHeight: number;
  viewport?: HTMLDivElement;
}) {
  return getCodeVirtualTotalSize({
    lineCount,
    lineHeight,
  });
}

function codeViewportHeight(viewport: HTMLDivElement) {
  return viewport.clientHeight || CODE_VIEWER_INITIAL_VIEWPORT_HEIGHT;
}

function shouldFitCodePerfectly({
  previousProjection,
  logicalScrollTop,
  viewportHeight,
}: {
  previousProjection: LastProjection | null;
  logicalScrollTop: number;
  viewportHeight: number;
}) {
  if (!previousProjection) return false;
  return (
    Math.abs(logicalScrollTop - previousProjection.logicalScrollTop) >
    viewportHeight + CODE_VIEWER_OVERSCAN_PX * 2
  );
}

function getCodeFitPerfectlyOverscanPx(lineHeight: number) {
  return Math.max(
    CODE_VIEWER_BLOCK_PADDING,
    Number.isFinite(lineHeight) ? lineHeight : 0,
  );
}

function codeRenderedWindow({
  physicalTotalSize,
  rowHost,
  scrollPageOffset,
  totalSize,
  viewportHeight,
  visibleLines,
}: {
  physicalTotalSize: number;
  rowHost: HTMLPreElement;
  scrollPageOffset: number;
  totalSize: number;
  viewportHeight: number;
  visibleLines: readonly CodeVirtualLine[];
}): CodeRenderedWindow {
  const renderedWindowElement = getCodeRenderedWindowElement(rowHost);
  if (!renderedWindowElement) {
    return {
      height: physicalTotalSize,
      rowOffset: 0,
      stickyOffset: 0,
      top: 0,
    };
  }

  const firstLine = visibleLines[0];
  const lastLine = visibleLines[visibleLines.length - 1];
  if (!firstLine || !lastLine) {
    return {
      height: 0,
      rowOffset: 0,
      stickyOffset: 0,
      top: 0,
    };
  }

  const top = getCodePagedLayoutTop({
    logicalTop: firstLine.start,
    scrollPageOffset,
    totalSize,
    viewportHeight,
  });
  const bottom = getCodePagedLayoutTop({
    logicalTop: lastLine.start + lastLine.size,
    scrollPageOffset,
    totalSize,
    viewportHeight,
  });
  const height = Math.max(0, bottom - top);

  return {
    height,
    rowOffset: top,
    stickyOffset: Math.min(0, viewportHeight - height),
    top,
  };
}

function syncCodeScrollLayers({
  renderedWindow,
  rowHost,
  totalHeight,
}: {
  renderedWindow: CodeRenderedWindow;
  rowHost: HTMLPreElement;
  totalHeight: string;
}) {
  const renderedWindowElement = getCodeRenderedWindowElement(rowHost);
  if (!renderedWindowElement) {
    setStyleValue(rowHost.style, "height", totalHeight);
    if (rowHost.parentElement instanceof HTMLElement) {
      setStyleValue(rowHost.parentElement.style, "height", totalHeight);
    }
    return;
  }

  const height = `${renderedWindow.height}px`;
  const top = `${renderedWindow.top}px`;
  const stickyOffset = `${renderedWindow.stickyOffset}px`;
  const offsetElement = getCodeRenderedWindowOffsetElement(
    renderedWindowElement,
  );

  setStyleValue(rowHost.style, "height", height);
  if (offsetElement) setStyleValue(offsetElement.style, "height", top);
  setStyleValue(renderedWindowElement.style, "height", height);
  setStyleValue(renderedWindowElement.style, "margin-top", "");
  setStyleValue(renderedWindowElement.style, "top", stickyOffset);
  setStyleValue(renderedWindowElement.style, "bottom", stickyOffset);

  if (renderedWindowElement.parentElement instanceof HTMLElement) {
    setStyleValue(renderedWindowElement.parentElement.style, "height", totalHeight);
  }
}

function getCodeRenderedWindowElement(rowHost: HTMLPreElement) {
  const element = rowHost.parentElement;
  if (
    element instanceof HTMLElement &&
    element.dataset.codeRenderWindow != null
  ) {
    return element;
  }
  return null;
}

function getCodeRenderedWindowOffsetElement(renderedWindowElement: HTMLElement) {
  const element = renderedWindowElement.previousElementSibling;
  if (
    element instanceof HTMLElement &&
    element.dataset.codeRenderOffset != null
  ) {
    return element;
  }
  return null;
}

function codeRowContentIdentity({
  syntax,
  text,
}: {
  syntax: CodeSyntax;
  text: string;
}) {
  return [text, syntax.identity, syntax.getLineVersion(text)].join("\u0000");
}

function createCodeRow(): CodeRowCache {
  const row = document.createElement("div");
  const gutterSpan = document.createElement("span");
  const contentSpan = document.createElement("span");

  row.className = codeRowClassName();
  row.style.position = "absolute";
  row.style.top = "0";
  row.style.left = "0";

  gutterSpan.className =
    "sticky left-0 z-10 flex-shrink-0 border-r px-2 pr-3 text-right text-muted-foreground/60 select-none";
  // The gutter must paint an opaque background so horizontally-scrolled code
  // never shows through the sticky line-number column. The theme's `--muted`
  // token is alpha-based (translucent), so the fill is mixed from the opaque
  // `--foreground`/`--background` pair instead.
  gutterSpan.style.backgroundColor = CODE_GUTTER_BACKGROUND;
  gutterSpan.dataset.codeGutter = "";
  gutterSpan.setAttribute("aria-hidden", "true");
  contentSpan.className = "whitespace-pre px-2";

  row.append(gutterSpan, contentSpan);

  return {
    contentIdentity: "",
    contentSpan,
    gutterSpan,
    layoutIdentity: "",
    row,
  };
}

function patchCodeRowLayout({
  gutterWidth,
  isHighlighted,
  metrics,
  lineNumber,
  row,
}: {
  gutterWidth: string;
  isHighlighted: boolean;
  metrics: CodeProjectionMetrics | undefined;
  lineNumber: number;
  row: CodeRowCache;
}) {
  incrementMetric(metrics, "layoutPatches");
  row.row.dataset.lineIndex = String(lineNumber - 1);
  row.row.dataset.lineNumber = String(lineNumber);
  setStyleValue(row.gutterSpan.style, "width", gutterWidth);
  setTextContent(row.gutterSpan, String(lineNumber));

  // Highlighted range: a continuous opaque band (no per-row borders) with a
  // single left accent stripe on the gutter that merges across adjacent lines.
  setStyleValue(
    row.row.style,
    "background-color",
    isHighlighted ? CODE_HIGHLIGHT_BACKGROUND : "",
  );
  setStyleValue(
    row.gutterSpan.style,
    "background-color",
    isHighlighted ? CODE_HIGHLIGHT_BACKGROUND : CODE_GUTTER_BACKGROUND,
  );
  setStyleValue(
    row.gutterSpan.style,
    "box-shadow",
    isHighlighted ? CODE_HIGHLIGHT_ACCENT_SHADOW : "",
  );
  setStyleValue(
    row.gutterSpan.style,
    "color",
    isHighlighted ? CODE_HIGHLIGHT_NUMBER_COLOR : "",
  );
}

function patchCodeRowContent({
  metrics,
  row,
  syntax,
  text,
}: {
  metrics: CodeProjectionMetrics | undefined;
  row: CodeRowCache;
  syntax: CodeSyntax;
  text: string;
}) {
  incrementMetric(metrics, "contentPatches");
  const renderText = getCodeLineRenderText(text);
  if (renderText.isTruncated) {
    row.row.dataset.codeLineTruncated = "";
    row.contentSpan.dataset.codeLineTruncated = "";
    row.contentSpan.setAttribute(
      "aria-label",
      `${text.length} character line preview; ${renderText.omittedCharacterCount} middle characters omitted.`,
    );
    row.contentSpan.title =
      "Long line preview. Copying the selected row copies the complete line.";
  } else {
    delete row.row.dataset.codeLineTruncated;
    delete row.contentSpan.dataset.codeLineTruncated;
    row.contentSpan.removeAttribute("aria-label");
    row.contentSpan.removeAttribute("title");
  }

  patchCodeContent(
    row.contentSpan,
    renderText.isTruncated ? null : syntax.getLineTokens(text),
    renderText.text,
    metrics,
  );
}

function patchCodeContent(
  contentSpan: HTMLSpanElement,
  leaves: readonly CodeTokenLeaf[] | null,
  text: string,
  metrics: CodeProjectionMetrics | undefined,
) {
  if (text === "") {
    contentSpan.replaceChildren();
    contentSpan.textContent = " ";
    return;
  }
  if (!leaves) {
    setTextContent(contentSpan, text);
    return;
  }

  contentSpan.replaceChildren();
  incrementMetric(metrics, "tokenSpanRebuilds");
  const fragment = document.createDocumentFragment();
  for (const leaf of leaves) {
    if (!leaf.kind) {
      fragment.append(document.createTextNode(leaf.text));
      continue;
    }
    const span = document.createElement("span");
    span.className = "cv-token-" + leaf.kind;
    span.textContent = leaf.text;
    fragment.append(span);
  }
  contentSpan.append(fragment);
}

function codeRowClassName() {
  return "absolute top-0 left-0 flex min-w-full";
}

function setStyleValue(
  style: CSSStyleDeclaration,
  propertyName: string,
  value: string,
) {
  if (style.getPropertyValue(propertyName) !== value) {
    style.setProperty(propertyName, value);
  }
}

function setTextContent(element: HTMLElement, text: string) {
  if (element.textContent !== text) {
    element.textContent = text;
  }
}

function incrementMetric(
  metrics: CodeProjectionMetrics | undefined,
  key: keyof CodeProjectionMetrics,
) {
  if (!metrics) return;
  metrics[key] += 1;
}

function setMetric(
  metrics: CodeProjectionMetrics | undefined,
  key: keyof CodeProjectionMetrics,
  value: number,
) {
  if (!metrics) return;
  metrics[key] = value;
}

"use client";

import * as React from "react";

import { useKeyedMountEffect } from "@/hooks/use-keyed-mount-effect";

import { joinEffectKey } from "@/lib/effect-key";
import {
  restoreTextViewerScrollInteractions,
  suspendTextViewerScrollInteractions,
  TEXT_SCROLL_INTERACTION_RESTORE_DELAY_MS,
  type ScrollInteractionSnapshot,
} from "./text-viewer-scroll-interactions";

export function useCodeProjectionScheduler({
  project,
  rowHostRef,
  viewportRef,
}: {
  project: () => boolean | void;
  rowHostRef?: React.RefObject<HTMLPreElement | null>;
  viewportRef: React.RefObject<HTMLDivElement | null>;
}) {
  const scheduledProjectionRef = React.useRef(0);
  const scrollInteractionRestoreRef = React.useRef(0);
  const scrollInteractionSnapshotRef =
    React.useRef<ScrollInteractionSnapshot | null>(null);

  const scheduleProjection = React.useCallback(() => {
    if (scheduledProjectionRef.current) return;
    const runProjection = () => {
      scheduledProjectionRef.current = requestAnimationFrame(() => {
        scheduledProjectionRef.current = 0;
        if (project()) {
          runProjection();
        }
      });
    };
    runProjection();
  }, [project]);

  useKeyedMountEffect(
    joinEffectKey(["code-project", project, scheduleProjection]),
    () => {
      if (project()) {
        scheduleProjection();
      }
      return () => {
        cancelScheduledProjection(scheduledProjectionRef);
      };
    },
  );

  useKeyedMountEffect(
    joinEffectKey([
      "code-project-listeners",
      scheduleProjection,
      rowHostRef,
      viewportRef,
    ]),
    () => {
      const viewport = viewportRef.current;
      if (!viewport) return;

      const handleScroll = () => {
        suspendTextViewerScrollInteractions({
          getInteractionTarget: () => rowHostRef?.current,
          getOverflowTarget: () => rowHostRef?.current?.parentElement,
          snapshotRef: scrollInteractionSnapshotRef,
        });
        if (scrollInteractionRestoreRef.current) {
          window.clearTimeout(scrollInteractionRestoreRef.current);
        }
        scrollInteractionRestoreRef.current = window.setTimeout(() => {
          scrollInteractionRestoreRef.current = 0;
          restoreTextViewerScrollInteractions(scrollInteractionSnapshotRef);
        }, TEXT_SCROLL_INTERACTION_RESTORE_DELAY_MS);
        scheduleProjection();
      };

      viewport.addEventListener("scroll", handleScroll, {
        passive: true,
      });
      const observer =
        typeof ResizeObserver === "undefined"
          ? null
          : new ResizeObserver(scheduleProjection);
      observer?.observe(viewport);

      return () => {
        viewport.removeEventListener("scroll", handleScroll);
        observer?.disconnect();
        cancelScheduledProjection(scheduledProjectionRef);
        if (scrollInteractionRestoreRef.current) {
          window.clearTimeout(scrollInteractionRestoreRef.current);
          scrollInteractionRestoreRef.current = 0;
        }
        restoreTextViewerScrollInteractions(scrollInteractionSnapshotRef);
      };
    },
  );
}

function cancelScheduledProjection(ref: React.MutableRefObject<number>) {
  if (!ref.current) return;
  cancelAnimationFrame(ref.current);
  ref.current = 0;
}

import type { NormalizedTextLineRange } from "./line-ranges";

export const LINE_SCROLL_HEADROOM = 64;

export interface LineRangeMetrics {
  startLine: number;
  endLine: number;
  lineHeight: number;
  viewportHeight: number;
  paddingStart?: number;
}

export function scrollTopForLineRangeMetrics({
  startLine,
  endLine,
  lineHeight,
  viewportHeight,
  paddingStart = 0,
}: LineRangeMetrics) {
  const rangeTop = paddingStart + (startLine - 1) * lineHeight;
  const rangeBottom = paddingStart + endLine * lineHeight;
  const rangeHeight = rangeBottom - rangeTop;
  const targetTop =
    rangeHeight <= viewportHeight
      ? rangeTop - (viewportHeight - rangeHeight) / 2
      : rangeTop - LINE_SCROLL_HEADROOM;

  return Math.max(0, targetTop);
}

export function scrollLineRangeMetricsIntoView({
  viewportElement,
  range,
  lineHeight,
  paddingStart,
  options,
}: {
  viewportElement: HTMLDivElement | null;
  range: NormalizedTextLineRange | null;
  lineHeight: number;
  paddingStart?: number;
  options?: ScrollToOptions;
}) {
  if (!viewportElement || !range) return;
  if (typeof viewportElement.scrollTo !== "function") return;

  viewportElement.scrollTo({
    top: scrollTopForLineRangeMetrics({
      startLine: range.start,
      endLine: range.end,
      lineHeight,
      paddingStart,
      viewportHeight: viewportElement.clientHeight,
    }),
    behavior: "smooth",
    ...options,
  });
}

