import {
  CODE_VIEWER_BLOCK_PADDING,
  CODE_VIEWER_LINE_CHECKPOINT_INTERVAL,
  CODE_VIEWER_SCROLL_REBASE_CONTAINER_PX,
  CODE_VIEWER_SCROLL_REBASE_TARGET_BOTTOM_PX,
  CODE_VIEWER_SCROLL_REBASE_TARGET_PX,
  CODE_VIEWER_SCROLL_REBASE_THRESHOLD_PX,
  CODE_VIEWER_SCROLL_REBASE_TRIGGER_PX,
} from "./code-viewer-scale";

export interface CodeVirtualLine {
  index: number;
  key: number;
  size: number;
  start: number;
}

export interface CodeVirtualLineWindow {
  lineCount: number;
  lineHeight: number;
  overscanPx: number;
  paddingStart: number;
  scrollTop: number;
  viewportHeight: number;
}

export interface CodeVirtualPixelWindow {
  bottom: number;
  top: number;
}

export interface CodeVirtualLineWindowResult {
  lines: CodeVirtualLine[];
  pixelWindow: CodeVirtualPixelWindow;
}

export interface CodeLineCheckpoint {
  index: number;
  start: number;
}

export interface CodeScrollRebaseState {
  scrollPageOffset: number;
}

export interface CodeScrollRebasePosition extends CodeScrollRebaseState {
  physicalScrollTop: number;
}

export function getCodeVirtualLines({
  lineCount,
  lineHeight,
  overscanPx,
  paddingStart,
  scrollTop,
  viewportHeight,
}: CodeVirtualLineWindow): CodeVirtualLine[] {
  return getCodeVirtualLineWindow({
    lineCount,
    lineHeight,
    overscanPx,
    paddingStart,
    scrollTop,
    viewportHeight,
  }).lines;
}

export function getCodeVirtualLineWindow({
  lineCount,
  lineHeight,
  overscanPx,
  paddingStart,
  scrollTop,
  viewportHeight,
}: CodeVirtualLineWindow): CodeVirtualLineWindowResult {
  const safeLineCount = safeCount(lineCount);
  const safeLineHeight = safeSize(lineHeight);
  if (safeLineCount === 0) {
    return {
      lines: [],
      pixelWindow: { bottom: 0, top: 0 },
    };
  }

  const safeScrollTop = Math.max(0, finiteNumber(scrollTop));
  const safeViewportHeight = Math.max(0, finiteNumber(viewportHeight));
  const safePaddingStart = safePadding(paddingStart);
  const totalSize = getCodeVirtualTotalSize({
    lineCount: safeLineCount,
    lineHeight: safeLineHeight,
    paddingStart: safePaddingStart,
  });
  const window = getCodeVirtualPixelWindow({
    overscanPx,
    scrollHeight: totalSize,
    scrollTop: safeScrollTop,
    viewportHeight: safeViewportHeight,
  });
  const start = getCodeLineIndexAtOffset({
    lineCount: safeLineCount,
    lineHeight: safeLineHeight,
    offset: window.top,
    paddingStart: safePaddingStart,
  });
  const end = Math.min(
    safeLineCount,
    getCodeLineIndexAfterOffset({
      lineCount: safeLineCount,
      lineHeight: safeLineHeight,
      offset: window.bottom,
      paddingStart: safePaddingStart,
    }),
  );

  return {
    lines: Array.from({ length: end - start }, (_, offset) => {
      const index = start + offset;
      return {
        index,
        key: index,
        size: safeLineHeight,
        start: safePaddingStart + index * safeLineHeight,
      };
    }),
    pixelWindow: window,
  };
}

export function getCodeLineCheckpoint({
  lineCount,
  lineHeight,
  offset,
  paddingStart = CODE_VIEWER_BLOCK_PADDING,
}: {
  lineCount: number;
  lineHeight: number;
  offset: number;
  paddingStart?: number;
}): CodeLineCheckpoint {
  const safeLineCount = safeCount(lineCount);
  if (safeLineCount === 0) {
    return {
      index: 0,
      start: safePadding(paddingStart),
    };
  }

  const safeLineHeight = safeSize(lineHeight);
  const safePaddingStart = safePadding(paddingStart);
  const lineIndex = clamp(
    Math.floor(Math.max(0, finiteNumber(offset) - safePaddingStart) / safeLineHeight),
    0,
    safeLineCount - 1,
  );
  const checkpointIndex =
    Math.floor(lineIndex / CODE_VIEWER_LINE_CHECKPOINT_INTERVAL) *
    CODE_VIEWER_LINE_CHECKPOINT_INTERVAL;

  return {
    index: checkpointIndex,
    start: safePaddingStart + checkpointIndex * safeLineHeight,
  };
}

export function getCodeLineIndexAtOffset({
  lineCount,
  lineHeight,
  offset,
  paddingStart = CODE_VIEWER_BLOCK_PADDING,
}: {
  lineCount: number;
  lineHeight: number;
  offset: number;
  paddingStart?: number;
}) {
  const safeLineCount = safeCount(lineCount);
  if (safeLineCount === 0) return 0;

  const safeLineHeight = safeSize(lineHeight);
  const checkpoint = getCodeLineCheckpoint({
    lineCount: safeLineCount,
    lineHeight: safeLineHeight,
    offset,
    paddingStart,
  });
  const indexFromCheckpoint = Math.floor(
    Math.max(0, finiteNumber(offset) - checkpoint.start) / safeLineHeight,
  );

  return clamp(checkpoint.index + indexFromCheckpoint, 0, safeLineCount - 1);
}

export function getCodeLineIndexAfterOffset({
  lineCount,
  lineHeight,
  offset,
  paddingStart = CODE_VIEWER_BLOCK_PADDING,
}: {
  lineCount: number;
  lineHeight: number;
  offset: number;
  paddingStart?: number;
}) {
  const safeLineCount = safeCount(lineCount);
  if (safeLineCount === 0) return 0;

  const safeLineHeight = safeSize(lineHeight);
  const checkpoint = getCodeLineCheckpoint({
    lineCount: safeLineCount,
    lineHeight: safeLineHeight,
    offset,
    paddingStart,
  });
  const indexFromCheckpoint = Math.ceil(
    Math.max(0, finiteNumber(offset) - checkpoint.start) / safeLineHeight,
  );

  return clamp(checkpoint.index + indexFromCheckpoint, 0, safeLineCount);
}

export function getCodeVirtualPixelWindow({
  overscanPx,
  scrollHeight,
  scrollTop,
  viewportHeight,
}: {
  overscanPx: number;
  scrollHeight: number;
  scrollTop: number;
  viewportHeight: number;
}): CodeVirtualPixelWindow {
  const safeOverscanPx = safePadding(overscanPx);
  const safeViewportHeight = Math.max(0, finiteNumber(viewportHeight));
  const windowHeight = safeViewportHeight + safeOverscanPx * 2;
  const safeScrollHeight = Math.max(0, finiteNumber(scrollHeight));

  if (windowHeight >= safeScrollHeight) {
    return { bottom: safeScrollHeight, top: 0 };
  }

  const scrollCenter = Math.max(0, finiteNumber(scrollTop)) + safeViewportHeight / 2;
  let top = scrollCenter - windowHeight / 2;
  let bottom = top + windowHeight;

  if (top < 0) {
    top = 0;
    bottom = windowHeight;
  }
  if (bottom > safeScrollHeight) {
    bottom = safeScrollHeight;
    top = safeScrollHeight - windowHeight;
  }

  return {
    bottom: Math.ceil(Math.max(bottom, top)),
    top: Math.floor(Math.max(0, top)),
  };
}

export function getCodeVirtualTotalSize({
  lineCount,
  lineHeight,
  paddingEnd = CODE_VIEWER_BLOCK_PADDING,
  paddingStart = CODE_VIEWER_BLOCK_PADDING,
}: {
  lineCount: number;
  lineHeight: number;
  paddingEnd?: number;
  paddingStart?: number;
}) {
  return (
    safePadding(paddingStart) +
    safeCount(lineCount) * safeSize(lineHeight) +
    safePadding(paddingEnd)
  );
}

export function getCodePhysicalScrollSize({
  totalSize,
  viewportHeight,
}: {
  totalSize: number;
  viewportHeight: number;
}) {
  const safeTotalSize = safeSize(totalSize);
  return shouldRebaseCodeScroll({ totalSize: safeTotalSize, viewportHeight })
    ? Math.min(safeTotalSize, CODE_VIEWER_SCROLL_REBASE_CONTAINER_PX)
    : safeTotalSize;
}

export function getCodeLogicalScrollTop({
  physicalScrollTop,
  scrollPageOffset,
  totalSize,
  viewportHeight,
}: {
  physicalScrollTop: number;
  scrollPageOffset: number;
  totalSize: number;
  viewportHeight: number;
}) {
  return clamp(
    finiteNumber(physicalScrollTop) + safePadding(scrollPageOffset),
    0,
    getCodeMaxLogicalScrollTop({ totalSize, viewportHeight }),
  );
}

export function resolveCodePhysicalScrollPosition({
  logicalScrollTop,
  scrollPageOffset,
  totalSize,
  viewportHeight,
}: {
  logicalScrollTop: number;
  scrollPageOffset: number;
  totalSize: number;
  viewportHeight: number;
}): CodeScrollRebasePosition {
  const safeLogicalScrollTop = clamp(
    finiteNumber(logicalScrollTop),
    0,
    getCodeMaxLogicalScrollTop({ totalSize, viewportHeight }),
  );

  if (!shouldRebaseCodeScroll({ totalSize, viewportHeight })) {
    return {
      physicalScrollTop: clamp(
        safeLogicalScrollTop,
        0,
        getCodeMaxPhysicalScrollTop({ totalSize, viewportHeight }),
      ),
      scrollPageOffset: 0,
    };
  }

  const currentPageOffset = clampCodeScrollPageOffset({
    scrollPageOffset,
    totalSize,
    viewportHeight,
  });
  const physicalScrollTop = safeLogicalScrollTop - currentPageOffset;
  const maxPhysicalScrollTop = getCodeMaxPhysicalScrollTop({
    totalSize,
    viewportHeight,
  });
  const maxPageOffset = getCodeMaxScrollPageOffset({ totalSize, viewportHeight });
  const shouldMoveDown =
    physicalScrollTop > CODE_VIEWER_SCROLL_REBASE_THRESHOLD_PX &&
    currentPageOffset < maxPageOffset;
  const shouldMoveUp =
    physicalScrollTop < CODE_VIEWER_SCROLL_REBASE_TRIGGER_PX &&
    currentPageOffset > 0;

  if (
    physicalScrollTop < 0 ||
    physicalScrollTop > maxPhysicalScrollTop ||
    shouldMoveDown ||
    shouldMoveUp
  ) {
    return resolveCodeScrollPageWindow({
      logicalScrollTop: safeLogicalScrollTop,
      preferredPhysicalScrollTop: shouldMoveUp
        ? Math.min(
            CODE_VIEWER_SCROLL_REBASE_TARGET_BOTTOM_PX,
            maxPhysicalScrollTop,
          )
        : CODE_VIEWER_SCROLL_REBASE_TARGET_PX,
      totalSize,
      viewportHeight,
    });
  }

  return {
    physicalScrollTop: roundCodeScrollPixel(
      clamp(physicalScrollTop, 0, maxPhysicalScrollTop),
    ),
    scrollPageOffset: currentPageOffset,
  };
}

export function getCodePagedLayoutTop({
  logicalTop,
  scrollPageOffset,
  totalSize,
  viewportHeight,
}: {
  logicalTop: number;
  scrollPageOffset: number;
  totalSize: number;
  viewportHeight: number;
}) {
  if (!shouldRebaseCodeScroll({ totalSize, viewportHeight })) {
    return finiteNumber(logicalTop);
  }
  return Math.max(0, finiteNumber(logicalTop) - safePadding(scrollPageOffset));
}

function shouldRebaseCodeScroll({
  totalSize,
  viewportHeight,
}: {
  totalSize: number;
  viewportHeight: number;
}) {
  return (
    getCodeMaxLogicalScrollTop({ totalSize, viewportHeight }) >
    CODE_VIEWER_SCROLL_REBASE_THRESHOLD_PX
  );
}

function getCodeMaxLogicalScrollTop({
  totalSize,
  viewportHeight,
}: {
  totalSize: number;
  viewportHeight: number;
}) {
  return Math.max(safeSize(totalSize) - Math.max(0, finiteNumber(viewportHeight)), 0);
}

function getCodeMaxPhysicalScrollTop({
  totalSize,
  viewportHeight,
}: {
  totalSize: number;
  viewportHeight: number;
}) {
  return Math.max(
    getCodePhysicalScrollSize({ totalSize, viewportHeight }) -
      Math.max(0, finiteNumber(viewportHeight)),
    0,
  );
}

function getCodeMaxScrollPageOffset({
  totalSize,
  viewportHeight,
}: {
  totalSize: number;
  viewportHeight: number;
}) {
  return Math.max(
    getCodeMaxLogicalScrollTop({ totalSize, viewportHeight }) -
      getCodeMaxPhysicalScrollTop({ totalSize, viewportHeight }),
    0,
  );
}

function clampCodeScrollPageOffset({
  scrollPageOffset,
  totalSize,
  viewportHeight,
}: {
  scrollPageOffset: number;
  totalSize: number;
  viewportHeight: number;
}) {
  return clamp(
    safePadding(scrollPageOffset),
    0,
    getCodeMaxScrollPageOffset({ totalSize, viewportHeight }),
  );
}

function resolveCodeScrollPageWindow({
  logicalScrollTop,
  preferredPhysicalScrollTop,
  totalSize,
  viewportHeight,
}: {
  logicalScrollTop: number;
  preferredPhysicalScrollTop: number;
  totalSize: number;
  viewportHeight: number;
}): CodeScrollRebasePosition {
  let physicalScrollTop = roundCodeScrollPixel(
    clamp(
      finiteNumber(preferredPhysicalScrollTop),
      0,
      getCodeMaxPhysicalScrollTop({ totalSize, viewportHeight }),
    ),
  );
  let scrollPageOffset = clampCodeScrollPageOffset({
    scrollPageOffset: logicalScrollTop - physicalScrollTop,
    totalSize,
    viewportHeight,
  });

  physicalScrollTop = roundCodeScrollPixel(
    clamp(
      logicalScrollTop - scrollPageOffset,
      0,
      getCodeMaxPhysicalScrollTop({ totalSize, viewportHeight }),
    ),
  );
  scrollPageOffset = clampCodeScrollPageOffset({
    scrollPageOffset: logicalScrollTop - physicalScrollTop,
    totalSize,
    viewportHeight,
  });

  return { physicalScrollTop, scrollPageOffset };
}

function finiteNumber(value: number) {
  return Number.isFinite(value) ? value : 0;
}

function roundCodeScrollPixel(value: number) {
  if (typeof window === "undefined") return Math.round(value);
  const ratio = window.devicePixelRatio || 1;
  return Math.round(value * ratio) / ratio;
}

function safeCount(value: number) {
  return Number.isFinite(value) && value > 0 ? Math.floor(value) : 0;
}

function safeSize(value: number) {
  return Number.isFinite(value) && value > 0 ? value : 1;
}

function safePadding(value: number) {
  return Number.isFinite(value) && value > 0 ? value : 0;
}

function clamp(value: number, min: number, max: number) {
  return Math.min(max, Math.max(min, value));
}

"use client";

import * as React from "react";

import { CODE_GUTTER_BACKGROUND } from "./code-viewer-projector";
import {
  CODE_VIEWER_BASE_FONT_PX,
  CODE_VIEWER_INITIAL_VIEWPORT_HEIGHT,
} from "./code-viewer-scale";
import {
  getCodePhysicalScrollSize,
  getCodeVirtualTotalSize,
} from "./code-viewer-virtualization";
import { ScrollArea } from "./scroll-area";

const CODE_VIEWER_DEFAULT_VIEWPORT_WIDTH = 800;

export function CodeViewerViewport({
  fontScale,
  gutterWidth,
  lineCount,
  lineHeight,
  onCopy,
  rowHostRef,
  viewportRef,
}: {
  fontScale: number;
  gutterWidth: string;
  lineCount: number;
  lineHeight: number;
  onCopy?: React.ClipboardEventHandler<HTMLPreElement>;
  rowHostRef: React.RefObject<HTMLPreElement | null>;
  viewportRef: React.RefObject<HTMLDivElement | null>;
}) {
  const fontSize = `${CODE_VIEWER_BASE_FONT_PX * fontScale}px`;
  const totalSize = getCodeVirtualTotalSize({
    lineCount,
    lineHeight,
  });
  const physicalTotalSize = getCodePhysicalScrollSize({
    totalSize,
    viewportHeight: CODE_VIEWER_INITIAL_VIEWPORT_HEIGHT,
  });

  return (
    <div className="bg-background relative min-h-0 flex-1">
      {/* Fixed full-height gutter rail, behind the scrolling content: the
          line-number column and its divider always reach the bottom of the
          viewport and never move while scrolling, because it lives outside the
          scroll container. The per-row gutters paint the numbers — and mask
          horizontally-scrolled code — on top of it. The viewport itself is
          transparent so this shows through below the last line. */}
      <div
        aria-hidden
        data-code-gutter-rail=""
        className="pointer-events-none absolute inset-y-0 left-0 z-0 border-r font-mono"
        style={{
          width: gutterWidth,
          backgroundColor: CODE_GUTTER_BACKGROUND,
          fontSize,
        }}
      />
      <ScrollArea
        className="absolute inset-0 z-10"
        viewportProps={{ style: { overflowAnchor: "none" } }}
        viewportRef={viewportRef}
      >
        <div
          data-code-scroll-spacer=""
          className="relative w-max min-w-full font-mono"
          style={{
            contain: "layout style",
            fontSize,
            height: physicalTotalSize,
            lineHeight: `${lineHeight}px`,
            minWidth: CODE_VIEWER_DEFAULT_VIEWPORT_WIDTH,
          }}
        >
          <div
            aria-hidden
            data-code-render-offset=""
            style={{
              contain: "layout size",
              height: 0,
            }}
          />
          <div
            data-code-render-window=""
            className="w-full"
            style={{
              bottom: 0,
              contain: "layout style inline-size",
              display: "flex",
              flexDirection: "column",
              height: physicalTotalSize,
              isolation: "isolate",
              position: "sticky",
              top: 0,
            }}
          >
            <pre
              onCopy={onCopy}
              ref={rowHostRef}
              className="relative w-full"
              suppressHydrationWarning
              style={{
                fontSize,
                height: physicalTotalSize,
                lineHeight: `${lineHeight}px`,
              }}
            />
          </div>
        </div>
      </ScrollArea>
    </div>
  );
}

"use client";

import * as React from "react";
import { Download } from "lucide-react";

import { cn } from "@/lib/utils";
import {
  ViewerDownloadError,
  type ViewerDownloadAction,
  type ViewerDownloadPayload,
} from "@/lib/viewer-download-actions";

import { Spinner } from "@/components/ui/spinner";

import { Button, buttonVariants } from "./button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "./dropdown-menu";
import { useKeyedMountEffect } from "@/hooks/use-keyed-mount-effect";
import { joinEffectKey } from "@/lib/effect-key";

export interface TriggerViewerDownloadOptions {
  signal?: AbortSignal;
}

export async function triggerViewerDownload(
  action: ViewerDownloadAction,
  options?: TriggerViewerDownloadOptions,
): Promise<void> {
  if (action.isDisabled) {
    throw new ViewerDownloadError({
      actionId: action.id,
      kind: "disabled",
      message: "This download is disabled.",
    });
  }

  let payload: ViewerDownloadPayload;
  try {
    payload = await action.getPayload(options);
  } catch (error) {
    if (isAbortError(error)) {
      throw new ViewerDownloadError({
        actionId: action.id,
        kind: "aborted",
        message: "Download was cancelled.",
        cause: error,
      });
    }
    throw new ViewerDownloadError({
      actionId: action.id,
      kind: "payload_failed",
      message: "Could not prepare this download.",
      cause: error,
    });
  }

  if (payload.kind === "none") return;
  if (payload.kind === "href") {
    try {
      clickDownload(payload.href, action.fileName);
    } catch (error) {
      throw new ViewerDownloadError({
        actionId: action.id,
        kind: "unsupported",
        message: "Could not start this download.",
        cause: error,
      });
    }
    return;
  }

  try {
    const blob =
      payload.kind === "blob"
        ? payload.blob
        : new Blob([payload.text], {
            type: payload.mimeType ?? "text/plain;charset=utf-8",
          });
    const url = URL.createObjectURL(blob);
    try {
      clickDownload(url, action.fileName);
    } finally {
      URL.revokeObjectURL(url);
    }
  } catch (error) {
    throw new ViewerDownloadError({
      actionId: action.id,
      kind: "unsupported",
      message: "Could not start this download.",
      cause: error,
    });
  }
}

export type ViewerDownloadErrorHandler = (
  error: ViewerDownloadError,
  action: ViewerDownloadAction,
) => void;

export interface ViewerDownloadTrigger {
  pendingActionId: string | null;
  triggerDownload: (action: ViewerDownloadAction) => void;
}

export interface ViewerDownloadTriggerOptions {
  /** Reports non-aborted action failures; visible failure UI belongs to consumers. */
  onError?: ViewerDownloadErrorHandler;
  resetKey?: unknown;
}

export interface ViewerDownloadControlProps {
  actions: Array<ViewerDownloadAction | null | undefined>;
  variant?: React.ComponentProps<typeof Button>["variant"];
  size?: React.ComponentProps<typeof Button>["size"];
  className?: string;
  showLabel?: boolean;
  /** Reports non-aborted action failures; visible failure UI belongs to consumers. */
  onError?: ViewerDownloadErrorHandler;
}

export interface ViewerDownloadButtonProps
  extends Omit<ViewerDownloadControlProps, "actions"> {
  action: ViewerDownloadAction | null;
}

export interface ViewerDownloadMenuProps
  extends Omit<ViewerDownloadControlProps, "actions"> {
  actions: ViewerDownloadAction[];
}

export function useViewerDownloadHref(
  action: ViewerDownloadAction | null,
): string | null {
  const shouldCreateHref = action?.origin !== "derived";
  const payload = shouldCreateHref ? getSynchronousPayload(action) : null;

  return shouldCreateHref && payload?.kind === "href" ? payload.href : null;
}

export function useViewerDownloadTrigger({
  onError,
  resetKey = "",
}: ViewerDownloadTriggerOptions = {}): ViewerDownloadTrigger {
  const [pendingActionId, setPendingActionId] = React.useState<string | null>(
    null,
  );
  const abortControllerRef = React.useRef<AbortController | null>(null);

  useKeyedMountEffect(joinEffectKey([resetKey]), () => {
    return () => {
      abortControllerRef.current?.abort();
      abortControllerRef.current = null;
    };
  });

  const triggerDownload = React.useCallback(
    (action: ViewerDownloadAction) => {
      abortControllerRef.current?.abort();
      const abortController = new AbortController();
      abortControllerRef.current = abortController;
      setPendingActionId(action.id);
      void triggerViewerDownload(action, { signal: abortController.signal })
        .catch((error) => {
          reportDownloadError(error, action, onError);
        })
        .finally(() => {
          if (abortControllerRef.current === abortController) {
            abortControllerRef.current = null;
            setPendingActionId(null);
          }
        });
    },
    [onError],
  );

  return { pendingActionId, triggerDownload };
}

export function ViewerDownloadControl({
  actions,
  variant = "ghost",
  size = "iconSm",
  className = "size-7",
  showLabel = false,
  onError,
}: ViewerDownloadControlProps) {
  const enabledActions = actions.filter(
    (action): action is ViewerDownloadAction => Boolean(action),
  );

  if (enabledActions.length <= 1) {
    return (
      <ViewerDownloadButton
        action={enabledActions[0] ?? null}
        variant={variant}
        size={size}
        className={className}
        showLabel={showLabel}
        onError={onError}
      />
    );
  }

  return (
    <ViewerDownloadMenu
      actions={enabledActions}
      variant={variant}
      size={size}
      className={className}
      showLabel={showLabel}
      onError={onError}
    />
  );
}

export function ViewerDownloadButton({
  action,
  variant = "ghost",
  size = "iconSm",
  className = "size-7",
  showLabel = false,
  onError,
}: ViewerDownloadButtonProps) {
  const href = useViewerDownloadHref(action);
  const label = action?.label ?? "Download";
  const disabled = !action || action.isDisabled;
  const hasDownloadHref = Boolean(href);
  const { pendingActionId, triggerDownload } = useViewerDownloadTrigger({
    onError,
    resetKey: action,
  });
  const isPending = Boolean(action && pendingActionId === action.id);

  const handleClick = React.useCallback(() => {
    if (!action || hasDownloadHref) return;
    triggerDownload(action);
  }, [action, hasDownloadHref, triggerDownload]);

  if (href) {
    return (
      <a
        href={href}
        download={action?.fileName}
        className={cn(buttonVariants({ variant, size }), className)}
        aria-label={label}
        title={label}
        data-slot="button"
      >
        <Download className={showLabel ? "mr-1.5 size-4" : undefined} />
        {showLabel ? label : null}
      </a>
    );
  }

  return (
    <Button
      variant={variant}
      size={size}
      className={className}
      aria-label={label}
      title={label}
      disabled={disabled || isPending}
      onClick={handleClick}
    >
      {isPending ? (
        <Spinner className="size-4 animate-spin" />
      ) : (
        <Download className={showLabel ? "mr-1.5 size-4" : undefined} />
      )}
      {showLabel ? label : null}
    </Button>
  );
}

export function ViewerDownloadMenu({
  actions,
  variant = "ghost",
  size = "iconSm",
  className = "size-7",
  showLabel = false,
  onError,
}: ViewerDownloadMenuProps) {
  const actionSetKey = actions.map((action) => action.id).join("\u0000");
  const label = "Download";
  const { pendingActionId, triggerDownload } = useViewerDownloadTrigger({
    onError,
    resetKey: actionSetKey,
  });

  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button
          variant={variant}
          size={size}
          className={className}
          aria-label={label}
          title={label}
          disabled={pendingActionId != null}
        >
          {pendingActionId != null ? (
            <Spinner className="size-4 animate-spin" />
          ) : (
            <Download className={showLabel ? "mr-1.5 size-4" : undefined} />
          )}
          {showLabel ? label : null}
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end">
        {actions.map((action) => (
          <DropdownMenuItem
            key={action.id}
            disabled={action.isDisabled || pendingActionId != null}
            onClick={() => triggerDownload(action)}
          >
            <Download />
            <span>{action.label}</span>
          </DropdownMenuItem>
        ))}
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

function clickDownload(href: string, fileName: string) {
  const anchor = document.createElement("a");
  anchor.href = href;
  anchor.download = fileName;
  anchor.rel = "noreferrer";
  document.body.appendChild(anchor);
  anchor.click();
  anchor.remove();
}

function getSynchronousPayload(
  action: ViewerDownloadAction | null,
): ViewerDownloadPayload | null {
  if (!action || action.isDisabled) return null;
  const payload = action.getPayload();
  return payload instanceof Promise ? null : payload;
}

function reportDownloadError(
  error: unknown,
  action: ViewerDownloadAction,
  onError: ViewerDownloadErrorHandler | undefined,
) {
  if (!(error instanceof ViewerDownloadError)) return;
  if (error.kind === "aborted") return;
  onError?.(error, action);
}

function isAbortError(error: unknown) {
  return error instanceof DOMException && error.name === "AbortError";
}

"use client";

import * as React from "react";
import { RotateCcw } from "lucide-react";

import { cn } from "@/lib/utils";
import type { ViewerDownloadAction } from "@/lib/viewer-download-actions";
import {
  toViewerErrorInfo,
  type ViewerErrorContext,
  type ViewerFormat,
} from "@/lib/viewer-errors";

import { Button } from "./button";
import { ViewerDownloadButton } from "./viewer-download";

export interface ViewerErrorStateProps extends ViewerErrorContext {
  error: unknown;
  download?: ViewerDownloadAction | null;
  className?: string;
  bare?: boolean;
  variant?: "card" | "document" | "inline";
  onRetry?: () => void;
}

export function ViewerErrorState({
  error,
  format,
  sourceKind,
  canDownload,
  retry,
  download,
  className,
  bare = false,
  variant = "card",
  onRetry,
}: ViewerErrorStateProps) {
  const info = toViewerErrorInfo(error, {
    format,
    sourceKind,
    canDownload: canDownload ?? Boolean(download && !download.isDisabled),
    retry,
  });
  const showRetry = info.isRetryable && onRetry;
  const showDownload =
    info.isDownloadUseful && download != null && !download.isDisabled;

  return (
    <div
      className={cn(errorStateClassName({ bare, variant }), className)}
      data-error-domain={info.domain}
      data-error-format={info.format}
      data-error-kind={info.kind}
      data-error-message={info.message}
      data-slot="viewer-error"
      role="alert"
    >
      <p>{info.userMessage}</p>
      {showRetry || showDownload ? (
        <div className="flex items-center gap-2">
          {showRetry ? (
            <Button variant="outline" size="sm" onClick={onRetry}>
              <RotateCcw className="mr-1.5 size-4" />
              Retry
            </Button>
          ) : null}
          {showDownload ? (
            <ViewerDownloadButton
              action={download}
              variant={showRetry ? "ghost" : "outline"}
              size="sm"
              className=""
              showLabel
            />
          ) : null}
        </div>
      ) : null}
    </div>
  );
}

export interface ViewerErrorBoundaryProps extends ViewerErrorContext {
  children: React.ReactNode;
  resetKey?: unknown;
  download?: ViewerDownloadAction | null;
  className?: string;
  bare?: boolean;
  variant?: "card" | "document" | "inline";
  mapError?: (error: unknown) => unknown;
  onRetry?: (error: unknown) => void;
  onCaughtError?: (error: unknown, errorInfo: React.ErrorInfo) => void;
}

export class ViewerErrorBoundary extends React.Component<
  ViewerErrorBoundaryProps,
  { error: unknown | null; retryKey: number }
> {
  state: Readonly<{ error: unknown | null; retryKey: number }> = {
    error: null,
    retryKey: 0,
  };

  componentDidUpdate(previousProps: ViewerErrorBoundaryProps) {
    if (
      previousProps.resetKey !== this.props.resetKey &&
      this.state.error != null
    ) {
      this.setState({ error: null });
    }
  }

  static getDerivedStateFromError(error: unknown) {
    return { error };
  }

  componentDidCatch(error: unknown, errorInfo: React.ErrorInfo) {
    this.props.onCaughtError?.(error, errorInfo);
  }

  render() {
    if (this.state.error != null) {
      const error = this.props.mapError
        ? this.props.mapError(this.state.error)
        : this.state.error;

      return (
        <ViewerErrorState
          error={error}
          format={this.props.format}
          sourceKind={this.props.sourceKind}
          canDownload={this.props.canDownload}
          retry={this.props.retry}
          download={this.props.download}
          className={this.props.className}
          bare={this.props.bare}
          variant={this.props.variant}
          onRetry={() => {
            this.setState((state) => ({
              error: null,
              retryKey: state.retryKey + 1,
            }));
            this.props.onRetry?.(this.state.error);
          }}
        />
      );
    }

    return (
      <React.Fragment key={this.state.retryKey}>
        {this.props.children}
      </React.Fragment>
    );
  }
}

function errorStateClassName({
  bare,
  variant,
}: {
  bare: boolean;
  variant: "card" | "document" | "inline";
}) {
  if (variant === "inline") {
    return "flex h-24 flex-col items-center justify-center gap-3 px-3 text-center text-xs text-muted-foreground";
  }
  return cn(
    "flex min-h-64 flex-col items-center justify-center gap-3 p-6 text-center text-sm text-muted-foreground",
    bare ? "bg-muted/20" : "rounded-xl border bg-muted/30",
    variant === "document" && "min-h-full",
  );
}

export type { ViewerFormat };

export interface TextLineRange {
  start: number;
  end: number;
}

export interface NormalizedTextLineRange extends TextLineRange {
  readonly normalized: true;
}

const clamp = (value: number, min: number, max: number) =>
  Math.min(max, Math.max(min, value));

export function normalizeTextLineRange(
  range: TextLineRange | null | undefined,
  lineCount: number,
): NormalizedTextLineRange | null {
  if (
    !range ||
    !Number.isFinite(range.start) ||
    !Number.isFinite(range.end) ||
    !Number.isFinite(lineCount) ||
    lineCount <= 0
  ) {
    return null;
  }

  const maxLine = Math.floor(lineCount);
  const rawStart = Math.trunc(range.start);
  const rawEnd = Math.trunc(range.end);
  const start = Math.min(rawStart, rawEnd);
  const end = Math.max(rawStart, rawEnd);

  if (end < 1 || start > maxLine) return null;

  return {
    start: clamp(start, 1, maxLine),
    end: clamp(end, 1, maxLine),
    normalized: true,
  };
}

export function isLineInRange(
  lineNumber: number,
  range: NormalizedTextLineRange | null,
) {
  return range != null && lineNumber >= range.start && lineNumber <= range.end;
}

import {
  isResourceError,
  isViewerFormatError,
  ViewerFormatError,
  type ViewerFormatErrorMapperOptions,
} from "@/lib/viewer-errors";
import type {
  ViewerContentIdentity,
  ViewerContentPayload,
  ViewerContentText,
} from "@/lib/viewer-resource";

export const DEFAULT_MAX_BYTES = 1_000_000;
export const DEFAULT_MAX_LINES = 10_000;
export const MAX_TEXT_RESOURCE_CACHE_ENTRIES = 64;
export const TEXT_LINE_DETACHMENT_SOURCE_MIN_LENGTH = 64 * 1024;
export const TEXT_LINE_DETACHMENT_MAX_LINE_LENGTH = 16 * 1024;

export interface TextViewerBounds {
  maxBytes?: number;
  maxLines?: number;
}

export type TextViewerTooLargeReason = "bytes" | "lines";
export type TextViewerBoundName = "maxBytes" | "maxLines";

export class TextViewerTooLargeError extends ViewerFormatError {
  readonly reason: TextViewerTooLargeReason;

  constructor(reason: TextViewerTooLargeReason) {
    super({
      format: "text",
      kind: "bounds",
      message: `Text file exceeds ${reason} limit`,
    });
    this.name = "TextViewerTooLargeError";
    this.reason = reason;
  }
}

export class TextViewerInvalidBoundsError extends ViewerFormatError {
  readonly boundName: TextViewerBoundName;

  constructor(boundName: TextViewerBoundName) {
    super({
      format: "text",
      kind: "bounds",
      message: `${boundName} must be a positive integer`,
    });
    this.name = "TextViewerInvalidBoundsError";
    this.boundName = boundName;
  }
}

export function toTextFormatError(
  error: unknown,
  options: ViewerFormatErrorMapperOptions = {
    kind: "load_failed",
    message: "Failed to load text.",
  },
): ViewerFormatError {
  if (isViewerFormatError(error)) return error;
  return new ViewerFormatError({
    format: "text",
    kind: options.kind,
    message: options.message,
    cause: error,
  });
}

export interface PreparedTextDocument {
  text: string;
  lines: readonly string[];
  lineCount: number;
}

interface TextResource {
  promise: Promise<PreparedTextDocument>;
  status: "pending" | "resolved" | "rejected";
  value?: PreparedTextDocument;
  error?: unknown;
}

const textResourceCache = new Map<string, TextResource>();

export type TextViewerContent = ViewerContentIdentity &
  ViewerContentPayload &
  ViewerContentText;

function textViewerResourceKey({
  content,
  retryVersion,
  bounds,
}: {
  content: ViewerContentIdentity;
  retryVersion: number;
  bounds: Required<TextViewerBounds>;
}) {
  return `${content.key}\0${retryVersion}\0${bounds.maxBytes}\0${bounds.maxLines}`;
}

export function clearTextViewerResourceCacheForTests() {
  textResourceCache.clear();
}

export function resolvedTextViewerBounds({
  maxBytes = DEFAULT_MAX_BYTES,
  maxLines = DEFAULT_MAX_LINES,
}: TextViewerBounds = {}): Required<TextViewerBounds> {
  return {
    maxBytes: resolveTextViewerBound(maxBytes, "maxBytes"),
    maxLines: resolveTextViewerBound(maxLines, "maxLines"),
  };
}

export function assertTextWithinBounds(
  text: string,
  bounds: Required<TextViewerBounds>,
) {
  prepareTextDocument(text, bounds);
}

// Split into stable source lines. The prose viewer may wrap each source line
// into several visual lines, but highlighting and scroll APIs stay source-line
// based.
export function splitTextLines(text: string) {
  return splitTextLinesForDocument(text).lines;
}

export function shouldDetachTextLine({
  lineLength,
  sourceLength,
}: {
  lineLength: number;
  sourceLength: number;
}) {
  return (
    sourceLength >= TEXT_LINE_DETACHMENT_SOURCE_MIN_LENGTH &&
    lineLength > 0 &&
    lineLength <= TEXT_LINE_DETACHMENT_MAX_LINE_LENGTH
  );
}

export function detachTextLine(line: string) {
  return line.length === 0 ? line : ` ${line}`.slice(1);
}

export function readTextResource({
  content,
  retryVersion,
  bounds,
}: {
  content: TextViewerContent;
  retryVersion: number;
  bounds: Required<TextViewerBounds>;
}) {
  return readTextDocument({ content, retryVersion, bounds }).text;
}

export function readTextDocument({
  content,
  retryVersion,
  bounds,
}: {
  content: TextViewerContent;
  retryVersion: number;
  bounds: Required<TextViewerBounds>;
}): PreparedTextDocument {
  const resourceKey = textViewerResourceKey({ content, retryVersion, bounds });
  const inlineText = inlineTextResource(content);
  if (inlineText != null) {
    return getInlineTextDocument({
      bounds,
      resourceKey,
      text: inlineText,
    });
  }

  const textResource = getTextResource({ content, resourceKey, bounds });

  if (textResource.status === "resolved") {
    return textResource.value ?? emptyPreparedTextDocument(bounds);
  }
  if (textResource.status === "rejected") throw textResource.error;

  throw textResource.promise;
}

export function prepareTextDocument(
  text: string,
  bounds: Required<TextViewerBounds>,
  options: { isByteLengthChecked?: boolean } = {},
): PreparedTextDocument {
  if (
    !options.isByteLengthChecked &&
    new TextEncoder().encode(text).byteLength > bounds.maxBytes
  ) {
    throw new TextViewerTooLargeError("bytes");
  }

  const lines = splitTextLinesForDocument(text, {
    maxLines: bounds.maxLines,
  }).lines;

  return {
    lineCount: lines.length,
    lines,
    text,
  };
}

function inlineTextResource(content: ViewerContentPayload) {
  return content.payload.kind === "text" ? content.payload.text : null;
}

function splitTextLinesForDocument(
  text: string,
  options: { maxLines?: number } = {},
) {
  const maxLines = options.maxLines ?? Number.POSITIVE_INFINITY;
  const lines: string[] = [];
  let lineStart = 0;

  for (let index = 0; index < text.length; index += 1) {
    const breakLength = textLineBreakLength(text, index);
    if (breakLength === 0) continue;

    appendTextLine(lines, text, lineStart, index, maxLines);
    index += breakLength - 1;
    lineStart = index + 1;
  }

  appendTextLine(lines, text, lineStart, text.length, maxLines);
  return { lines };
}

function appendTextLine(
  lines: string[],
  text: string,
  start: number,
  end: number,
  maxLines: number,
) {
  if (lines.length >= maxLines) {
    throw new TextViewerTooLargeError("lines");
  }

  const line = text.slice(start, end);
  lines.push(
    shouldDetachTextLine({
      lineLength: end - start,
      sourceLength: text.length,
    })
      ? detachTextLine(line)
      : line,
  );
}

function textLineBreakLength(text: string, index: number) {
  const code = text.charCodeAt(index);
  if (code === 0x0d) {
    return text.charCodeAt(index + 1) === 0x0a ? 2 : 1;
  }
  return code === 0x0a || code === 0x2028 || code === 0x2029 ? 1 : 0;
}

function getInlineTextDocument({
  bounds,
  resourceKey,
  text,
}: {
  bounds: Required<TextViewerBounds>;
  resourceKey: string;
  text: string;
}) {
  const cached = textResourceCache.get(resourceKey);
  if (cached?.status === "resolved" && cached.value) return cached.value;

  const document = prepareTextDocument(text, bounds);
  textResourceCache.set(resourceKey, {
    promise: Promise.resolve(document),
    status: "resolved",
    value: document,
  });
  trimTextResourceCache();
  return document;
}

function getTextResource({
  content,
  resourceKey,
  bounds,
}: {
  content: TextViewerContent;
  resourceKey: string;
  bounds: Required<TextViewerBounds>;
}) {
  let textResource = textResourceCache.get(resourceKey);
  if (!textResource) {
    const nextResource: TextResource = {
      status: "pending",
      promise: readBoundedTextResource(content, bounds).then((text) =>
        prepareTextDocument(text, bounds, { isByteLengthChecked: true }),
      ),
    };
    nextResource.promise.then(
      (value) => {
        nextResource.status = "resolved";
        nextResource.value = value;
      },
      (error) => {
        nextResource.status = "rejected";
        nextResource.error = error;
      },
    );
    textResource = nextResource;
    textResourceCache.set(resourceKey, textResource);
    trimTextResourceCache();
  }
  return textResource;
}

async function readBoundedTextResource(
  content: ViewerContentText,
  bounds: Required<TextViewerBounds>,
) {
  try {
    return await content.readText(bounds);
  } catch (error) {
    if (isResourceError(error)) throw error;
    throw toTextFormatError(error);
  }
}

function emptyPreparedTextDocument(
  bounds: Required<TextViewerBounds>,
): PreparedTextDocument {
  return prepareTextDocument("", bounds);
}

function resolveTextViewerBound(value: number, boundName: TextViewerBoundName) {
  if (!Number.isSafeInteger(value) || value < 1) {
    throw new TextViewerInvalidBoundsError(boundName);
  }
  return value;
}

function trimTextResourceCache() {
  while (textResourceCache.size > MAX_TEXT_RESOURCE_CACHE_ENTRIES) {
    const firstKey = textResourceCache.keys().next().value;
    if (firstKey === undefined) return;
    textResourceCache.delete(firstKey);
  }
}

export type FileCategory =
  | "pdf"
  | "docx"
  | "xlsx"
  | "pptx"
  | "csv"
  | "image"
  | "markdown"
  | "html"
  | "email"
  | "text"
  | "unsupported";

export type ViewerSource = UrlViewerSource | TextSource | BlobViewerSource;

export interface UrlViewerSource {
  kind: "url";
  url: string;
  fileName?: string;
  mimeType?: string;
  downloadUrl?: string;
  identityKey?: string;
}

export interface TextSource {
  kind: "text";
  text: string;
  fileName?: string;
  mimeType?: string;
  identityKey?: string;
}

export interface BlobViewerSource {
  kind: "blob";
  blob: Blob;
  identityKey: string;
  fileName?: string;
  mimeType?: string;
  downloadUrl?: string;
}

export interface ViewerDescriptor {
  source: ViewerSource;
  category: FileCategory;
  identityKey: string;
  displayName: string;
  fileName: string;
  mimeType?: string;
}

