}

export function isAbortError(error: unknown): boolean {
  return (
    (error instanceof DOMException && error.name === "AbortError") ||
    (error instanceof Error && error.name === "AbortError")
  );
}

export function isResourceError(error: unknown): error is ResourceError {
  return (
    error instanceof ResourceError ||
    isErrorLike(error, "ResourceError", "resource")
  );
}

export function isViewerFormatError(
  error: unknown,
): error is ViewerFormatError {
  return (
    error instanceof ViewerFormatError ||
    isErrorLike(error, "ViewerFormatError", "format")
  );
}

export function isViewerStateError(error: unknown): error is ViewerStateError {
  return (
    error instanceof ViewerStateError ||
    isErrorLike(error, "ViewerStateError", "state")
  );
}

export function isViewerUnsupportedError(
  error: unknown,
): error is ViewerUnsupportedError {
  return (
    error instanceof ViewerUnsupportedError ||
    isErrorLike(error, "ViewerUnsupportedError", "unsupported")
  );
}

export function toViewerErrorInfo(
  error: unknown,
  context: ViewerErrorContext = {},
): ViewerErrorInfo {
  const canDownload = context.canDownload ?? true;

  if (isResourceError(error)) {
    return {
      domain: "resource",
      format: context.format,
      kind: error.kind,
      message: error.message,
      status: error.status,
      isRetryable: retryable(
        context,
        resourceErrorDefaultRetry(error, context),
      ),
      isDownloadUseful: canDownload && error.kind !== "aborted",
      userMessage: resourceErrorUserMessage(error),
      cause: error.cause,
    };
  }

  if (isViewerFormatError(error)) {
    const format = error.format ?? context.format;
    return {
      domain: "format",
      format,
      kind: error.kind,
      message: error.message,
      isRetryable: retryable(
        context,
        formatErrorDefaultRetry(error, context, format),
      ),
      isDownloadUseful: canDownload,
      userMessage: formatErrorUserMessage(format, error.kind, error),
      cause: error.cause,
    };
  }

  if (isViewerStateError(error)) {
    return {
      domain: "state",
      format: error.format ?? context.format,
      kind: error.kind,
      message: error.message,
      isRetryable: retryable(context, false),
      isDownloadUseful: canDownload,
      userMessage: stateErrorUserMessage(error.kind),
      cause: error.cause,
    };
  }

  if (isViewerUnsupportedError(error)) {
    return {
      domain: "unsupported",
      format: error.format ?? context.format,
      kind: "unsupported",
      message: error.message,
      isRetryable: retryable(context, false),
      isDownloadUseful: canDownload,
      userMessage: "This file cannot be previewed here.",
      cause: error.cause,
    };
  }

  if (isAbortError(error)) {
    return {
      domain: "resource",
      format: context.format,
      kind: "aborted",
      message: "Loading was cancelled.",
      isRetryable: retryable(context, false),
      isDownloadUseful: false,
      userMessage: "Loading was cancelled.",
      cause: error,
    };
  }

  const message = error instanceof Error ? error.message : String(error);
  return {
    domain: "unknown",
    format: context.format,
    kind: "unknown",
    message,
    isRetryable: retryable(context, unknownErrorDefaultRetry(context)),
    isDownloadUseful: canDownload,
    userMessage: fallbackUserMessage(context.format),
    cause: error,
  };
}

function isErrorLike(error: unknown, name: string, domain: ViewerErrorDomain) {
  if (!error || typeof error !== "object") return false;
  const candidate = error as {
    name?: unknown;
    domain?: unknown;
    kind?: unknown;
  };
  return (
    (candidate.name === name || candidate.domain === domain) &&
    typeof candidate.kind === "string"
  );
}

function retryable(context: ViewerErrorContext, fallback: boolean) {
  if (context.retry === "always") return true;
  if (context.retry === "never") return false;
  return fallback;
}

function resourceErrorDefaultRetry(
  error: ResourceError,
  context: ViewerErrorContext,
) {
  if (error.kind === "aborted") return false;
  if (error.kind === "invalid_range") return false;
  if (error.kind === "too_large") return false;
  if (error.kind === "unsupported_capability") return false;
  return context.sourceKind === "url";
}

function formatErrorDefaultRetry(
  error: ViewerFormatError,
  context: ViewerErrorContext,
  format: ViewerFormat | undefined,
) {
  if (format === "text" && error.kind === "bounds") return false;
  if (error.kind === "disposed") return false;
  if (error.kind === "index_out_of_range") return false;
  if (format === "docx") return true;
  return context.sourceKind === "url";
}

function unknownErrorDefaultRetry(context: ViewerErrorContext) {
  if (context.format === "docx") return true;
  return context.sourceKind === "url";
}

function resourceErrorUserMessage(error: ResourceError) {
  if (error.kind === "http_error") {
    return error.status
      ? `Failed to load file: ${error.status}.`
      : "Couldn't load this file.";
  }
  if (error.kind === "fetch_failed") return "Couldn't load this file.";
  if (error.kind === "aborted") return "Loading was cancelled.";
  if (error.kind === "invalid_range") return "This source range is invalid.";
  if (error.kind === "too_large") {
    return error.tooLargeReason === "lines"
      ? "This file has too many lines to preview."
      : "This file is too large to preview.";
  }
  if (error.kind === "partial_content") {
    return "This source returned partial content and cannot be previewed here.";
  }
  if (error.kind === "unsupported_capability") {
    return "This source cannot be previewed here.";
  }
  return "Couldn't load this file.";
}

function formatErrorUserMessage(
  format: ViewerFormat | undefined,
  kind: string,
  error?: unknown,
) {
  if (format === "pdf") return "Couldn't load this PDF.";
  if (format === "image") {
    if (kind === "index_out_of_range")
      return "This image page is out of range.";
    if (kind === "decode_failed") return "Couldn't decode this image.";
    return "Couldn't load this image.";
  }
  if (format === "text") {
    if (kind === "render_failed") return "Couldn't render this text file.";
    if (kind === "bounds") {
      const boundsError = error as {
        reason?: unknown;
        boundName?: unknown;
      };
      if (boundsError.reason === "lines") {
        return "This text file has too many lines to preview.";
      }
      if (boundsError.reason === "bytes") {
        return "This text file is too large to preview.";
      }
      if (typeof boundsError.boundName === "string") {
        return "Text viewer bounds are invalid.";
      }
    }
    return "Couldn't load this text file.";
  }
  if (format === "csv") return "Couldn't parse this table.";
  if (format === "docx") return "Couldn't render this document.";
  if (format === "xlsx") return "Couldn't parse this spreadsheet.";
  if (format === "pptx") {
    if (kind === "render_failed") return "Couldn't render this slide.";
    return "Couldn't load this presentation.";
  }
  return "Couldn't load this file.";
}

function stateErrorUserMessage(kind: ViewerStateErrorKind) {
  if (kind === "invalid_bounds") return "Viewer bounds are invalid.";
  if (kind === "invalid_target") return "The requested target is invalid.";
  if (kind === "out_of_range") return "The requested item is out of range.";
  if (kind === "stale_resource") return "This viewer state is no longer valid.";
  return "Couldn't load this file.";
}

function fallbackUserMessage(format: ViewerFormat | undefined) {
  if (format === "pdf") return "Couldn't load this PDF.";
  if (format === "image") return "Couldn't load this image.";
  if (format === "text") return "Couldn't load this text file.";
  if (format === "csv") return "Couldn't parse this table.";
  if (format === "docx") return "Couldn't load this document.";
  if (format === "xlsx") return "Couldn't load this spreadsheet.";
  if (format === "pptx") return "Couldn't load this presentation.";
  return "Couldn't load this file.";
}

"use client";

import * as React from "react";
import { useMountEffect } from "@/hooks/use-mount-effect";

export function useIsClient(): boolean {
  const [isClient, setIsClient] = React.useState(false);

  useMountEffect(() => {
    setIsClient(true);
  });

  return isClient;
}

export const CODE_VIEWER_LONG_LINE_RENDER_MAX = 4096;

const CODE_VIEWER_LONG_LINE_HEAD_CHARS = 3072;
const CODE_VIEWER_LONG_LINE_TAIL_CHARS = 768;

export type CodeLineRenderText = {
  isTruncated: boolean;
  omittedCharacterCount: number;
  text: string;
};

export function getCodeLineRenderText(text: string): CodeLineRenderText {
  if (text.length <= CODE_VIEWER_LONG_LINE_RENDER_MAX) {
    return {
      isTruncated: false,
      omittedCharacterCount: 0,
      text,
    };
  }

  const omittedCharacterCount =
    text.length -
    CODE_VIEWER_LONG_LINE_HEAD_CHARS -
    CODE_VIEWER_LONG_LINE_TAIL_CHARS;

  return {
    isTruncated: true,
    omittedCharacterCount,
    text:
      text.slice(0, CODE_VIEWER_LONG_LINE_HEAD_CHARS) +
      ` ... ${omittedCharacterCount} chars omitted ... ` +
      text.slice(-CODE_VIEWER_LONG_LINE_TAIL_CHARS),
  };
}

export function getCodeLongLineSelectionText({
  rowHost,
  selection,
  textLines,
}: {
  rowHost: HTMLPreElement;
  selection: Selection | null;
  textLines: readonly string[];
}) {
  if (!selection || selection.isCollapsed || selection.rangeCount === 0) {
    return null;
  }

  const selectedLineIndexes = new Set<number>();
  let includesTruncatedLine = false;

  for (let rangeIndex = 0; rangeIndex < selection.rangeCount; rangeIndex += 1) {
    const range = selection.getRangeAt(rangeIndex);
    if (!rangeIntersectsNode(range, rowHost)) continue;

    for (const row of rowHost.querySelectorAll<HTMLElement>(
      "[data-line-index]",
    )) {
      if (!rangeIntersectsNode(range, row)) continue;

      const lineIndex = Number(row.dataset.lineIndex);
      if (
        Number.isInteger(lineIndex) &&
        lineIndex >= 0 &&
        lineIndex < textLines.length
      ) {
        selectedLineIndexes.add(lineIndex);
      }
      if (row.dataset.codeLineTruncated != null) {
        includesTruncatedLine = true;
      }
    }
  }

  if (!includesTruncatedLine || selectedLineIndexes.size === 0) return null;

  return Array.from(selectedLineIndexes)
    .sort((first, second) => first - second)
    .map((lineIndex) => textLines[lineIndex] ?? "")
    .join("\n");
}

function rangeIntersectsNode(range: Range, node: Node) {
  try {
    if (range.intersectsNode(node)) return true;
  } catch {
    // Detached test DOM can make intersectsNode throw even when the selected
    // content is plainly inside the row.
  }
  return (
    node === range.commonAncestorContainer ||
    node.contains(range.commonAncestorContainer)
  );
}

"use client";

import * as React from "react";

import { useKeyedMountEffect } from "@/hooks/use-keyed-mount-effect";
import { joinEffectKey } from "@/lib/effect-key";

export const TEXT_SCROLL_INTERACTION_RESTORE_DELAY_MS = 120;

export type ScrollInteractionSnapshot = {
  overflowTarget: HTMLElement | null;
  overflowX: InlineStyleSnapshot | null;
  pointerEvents: InlineStyleSnapshot;
  target: HTMLElement;
};

type InlineStyleSnapshot = {
  priority: string;
  value: string;
};

export function useTextViewerScrollInteractions<Viewport extends HTMLElement>({
  getInteractionTarget,
  getOverflowTarget,
  onScroll,
  viewportRef,
}: {
  getInteractionTarget: () => HTMLElement | null | undefined;
  getOverflowTarget?: () => HTMLElement | null | undefined;
  onScroll: (viewport: Viewport) => void;
  viewportRef: React.RefObject<Viewport | null>;
}) {
  const restoreTimerRef = React.useRef(0);
  const snapshotRef = React.useRef<ScrollInteractionSnapshot | null>(null);

  useKeyedMountEffect(
    joinEffectKey([
      getInteractionTarget,
      getOverflowTarget,
      onScroll,
      viewportRef,
    ]),
    () => {
      const viewport = viewportRef.current;
      if (!viewport) return;

      const handleScroll = () => {
        suspendTextViewerScrollInteractions({
          getInteractionTarget,
          getOverflowTarget,
          snapshotRef,
        });
        if (restoreTimerRef.current) {
          window.clearTimeout(restoreTimerRef.current);
        }
        restoreTimerRef.current = window.setTimeout(() => {
          restoreTimerRef.current = 0;
          restoreTextViewerScrollInteractions(snapshotRef);
        }, TEXT_SCROLL_INTERACTION_RESTORE_DELAY_MS);
        onScroll(viewport);
      };

      viewport.addEventListener("scroll", handleScroll, { passive: true });
      return () => {
        viewport.removeEventListener("scroll", handleScroll);
        if (restoreTimerRef.current) {
          window.clearTimeout(restoreTimerRef.current);
          restoreTimerRef.current = 0;
        }
        restoreTextViewerScrollInteractions(snapshotRef);
      };
    },
  );
}

export function suspendTextViewerScrollInteractions({
  getInteractionTarget,
  getOverflowTarget,
  snapshotRef,
}: {
  getInteractionTarget: () => HTMLElement | null | undefined;
  getOverflowTarget?: () => HTMLElement | null | undefined;
  snapshotRef: React.MutableRefObject<ScrollInteractionSnapshot | null>;
}) {
  const target = getInteractionTarget();
  if (!target) {
    restoreTextViewerScrollInteractions(snapshotRef);
    return;
  }

  const overflowTarget = isMobileSafari()
    ? (getOverflowTarget?.() ?? target.parentElement ?? target)
    : null;
  const current = snapshotRef.current;
  if (
    current &&
    current.target === target &&
    current.overflowTarget === overflowTarget
  ) {
    target.style.pointerEvents = "none";
    overflowTarget?.style.setProperty("overflow-x", "hidden");
    return;
  }

  restoreTextViewerScrollInteractions(snapshotRef);
  snapshotRef.current = {
    overflowTarget,
    overflowX: overflowTarget
      ? readInlineStyle(overflowTarget, "overflow-x")
      : null,
    pointerEvents: readInlineStyle(target, "pointer-events"),
    target,
  };
  target.style.pointerEvents = "none";
  overflowTarget?.style.setProperty("overflow-x", "hidden");
}

export function restoreTextViewerScrollInteractions(
  snapshotRef: React.MutableRefObject<ScrollInteractionSnapshot | null>,
) {
  const snapshot = snapshotRef.current;
  if (!snapshot) return;

  restoreInlineStyle(snapshot.target, "pointer-events", snapshot.pointerEvents);
  if (snapshot.overflowTarget && snapshot.overflowX) {
    restoreInlineStyle(
      snapshot.overflowTarget,
      "overflow-x",
      snapshot.overflowX,
    );
  }
  snapshotRef.current = null;
}

function isMobileSafari() {
  if (typeof navigator === "undefined") return false;
  const userAgent = navigator.userAgent;
  return (
    /Safari/i.test(userAgent) &&
    /Mobile/i.test(userAgent) &&
    !/CriOS|FxiOS|EdgiOS/i.test(userAgent)
  );
}

function readInlineStyle(
  element: HTMLElement,
  propertyName: string,
): InlineStyleSnapshot {
  return {
    priority: element.style.getPropertyPriority(propertyName),
    value: element.style.getPropertyValue(propertyName),
  };
}

function restoreInlineStyle(
  element: HTMLElement,
  propertyName: string,
  snapshot: InlineStyleSnapshot,
) {
  if (!snapshot.value) {
    element.style.removeProperty(propertyName);
    return;
  }
  element.style.setProperty(propertyName, snapshot.value, snapshot.priority);
}
